def _sql_select_source_cte_step(
    ctx: CompilationContext,
    source_ref: ServerPlanRefId,
    *,
    context: str,
) -> tuple[SqlDynamicSelectStmt, list[tuple[str, object]] | None, CtePublicationContract]:
    source_ref_id = str(source_ref)
    source_cte = ctx.cte_refs.get(source_ref_id)
    if not isinstance(source_cte, CteReference):
        msg = f"{context} requires a SQL-visible source relation for {source_ref_id!r}; runtime-ref map construction is not allowed."
        raise RuntimeError(msg)
    return (
        SqlDynamicSelectStmt(
            SqlTableName(source_cte.ref_id),
            columns=([SqlColumnName(column) for column in source_cte.columns] if source_cte.columns is not None else None),
        ),
        ([(source_cte.ref_id, source_cte.auxiliary_query)] if source_cte.auxiliary_query is not None else None),
        CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(source_cte.columns or ()),
            column_type_hints=source_cte.column_type_hints,
            relation_contract=CteRelationContract.source_cte(source_cte_ref=str(source_cte.ref_id)),
        ),
    )


