@pure_lazy
def _require_concrete_lazy_input(source: LazyResult[Any], *, context: str) -> Any:
    shape = inspect_server_value_shape_for_planning(
        source,
        site=context,
    )
    if shape.symbolic_ref_id is not None:
        msg = f"{context} requires a concrete literal API input, got published ref {shape.symbolic_ref_id!r}"
        raise TypeError(msg)
    if not shape.has_literal_value:
        msg = f"{context} requires a concrete literal API input"
        raise TypeError(msg)
    return shape.literal_value


@pure_lazy
def _normalize_literal_lazy_input[T](value: T | LazyResult[T], *, context: str) -> T | LazyResult[T]:
    if not isinstance(value, LazyResult):
        return value
    return cast("T | LazyResult[T]", _require_concrete_lazy_input(value, context=context))


