@pure_lazy
def _require_object_source_ref[T](
    value: T | LazyResult[T] | ObjectServerRef[T],
    *,
    context: str,
) -> ObjectServerRef[T]:
    if isinstance(value, ObjectServerRef):
        return value
    if isinstance(value, LazyResult):
        shape = inspect_server_value_shape_for_planning(value, site=context)
        if shape.symbolic_ref_id is None:
            if not shape.has_literal_value:
                msg = f"{context} requires a literal value or a published object ref"
                raise TypeError(msg)
            return cast("ObjectServerRef[T]", ServerRefs.object(shape.literal_value))
        return cast(
            "ObjectServerRef[T]",
            ServerRefs.from_ref_id(shape.symbolic_ref_id, variant="object"),
        )
    return cast("ObjectServerRef[T]", ServerRefs.object(value))


@pure_lazy
def _require_object_sequence_source_ref[T](
    value: Sequence[T] | LazyResult[Sequence[T]] | ObjectSequenceServerRef[T],
    *,
    context: str,
) -> ObjectSequenceServerRef[T]:
    if isinstance(value, ObjectSequenceServerRef):
        return value
    if isinstance(value, LazyResult):
        shape = inspect_server_value_shape_for_planning(value, site=context)
        if shape.symbolic_ref_id is None:
            if not shape.has_literal_value:
                msg = f"{context} requires a literal value or a published object-sequence ref"
                raise TypeError(msg)
            literal_sequence = cast("Sequence[T]", shape.literal_value)
            return ServerRefs.object_sequence(literal_sequence)
        return ServerRefs.from_ref_id(shape.symbolic_ref_id, variant="object_sequence")
    return ServerRefs.object_sequence(value)


@pure_lazy
def _require_scalar_sequence_source_ref[T](
    value: Sequence[T] | LazyResult[Sequence[T]] | ScalarSequenceServerRef[T],
    *,
    context: str,
) -> ScalarSequenceServerRef[T]:
    if isinstance(value, ScalarSequenceServerRef):
        return value
    if isinstance(value, LazyResult):
        shape = inspect_server_value_shape_for_planning(value, site=context)
        if shape.symbolic_ref_id is None:
