@pure_lazy
def _optional_database_object_model(
    value: object,
) -> type[DatabaseObjectRow] | None:
    """Narrow immutable model metadata without consulting transaction state."""
    if value is None:
        return None
    assert isinstance(value, type)
    assert issubclass(value, DatabaseObjectRow)
    return value


@pure_lazy
def _table_name_set(value: object | None) -> set[SqlTableName] | None:
    """Brand supplied table identities without schema or connection access."""
    if value is None:
        return None
    if not isinstance(value, list | tuple | set | frozenset):
        raise TypeError("Speculative table names must be a finite collection")
    table_names: set[SqlTableName] = set()
    for item in value:
        if not isinstance(item, str):
            raise TypeError("Speculative table names must be strings")
        table_names.add(SqlTableName(item))
    return table_names


class _NamedSpeculativeBranchScope(BaseModel, frozen=True):
    """Immutable locator for planning hints, never publication authority."""

    branch_name: BranchName
    workspace_id: WorkspaceId


@dataclass(frozen=True, slots=True)
class _ConnectionSpeculativePublishFacts:
    touched_tables: frozenset[SqlTableName] = frozenset()
    non_insert_tables: frozenset[SqlTableName] = frozenset()
    deleted_tables: frozenset[SqlTableName] = frozenset()
    staged_commit_ids: frozenset[StagedCommitId] = frozenset()
    named_branch_scopes: frozenset[_NamedSpeculativeBranchScope] = frozenset()

    @property
    def insert_only_tables(self: _ConnectionSpeculativePublishFacts) -> frozenset[SqlTableName]:
        return self.touched_tables - self.non_insert_tables - self.deleted_tables

    def merged_with(
        self: _ConnectionSpeculativePublishFacts,
        other: _ConnectionSpeculativePublishFacts,
    ) -> _ConnectionSpeculativePublishFacts:
        return _ConnectionSpeculativePublishFacts(
            touched_tables=self.touched_tables | other.touched_tables,
            non_insert_tables=self.non_insert_tables | other.non_insert_tables,
            deleted_tables=self.deleted_tables | other.deleted_tables,
            staged_commit_ids=self.staged_commit_ids | other.staged_commit_ids,
            named_branch_scopes=self.named_branch_scopes | other.named_branch_scopes,
        )


@dataclass(frozen=True, slots=True)
class PhysicalOwnerMutationPlan[T: DatabaseObjectRow]:
