        branch_ref_id=resolve_input.branch_ref_id,
    )


@pure_lazy
def _resolve_type_names_lazy_result(
    txn: LazyReadTransaction,
    *,
    context_refs: VersionedLazyContextRefs,
    object_ids: Sequence[SysId] | LazyResult[Sequence[SysId]] | ScalarSequenceServerRef[SysId],
    candidate_models: Mapping[str, type[DatabaseObjectRow]],
    graph_id: SysId | LazyResult[SysId] | ScalarServerRef[SysId] | None = None,
) -> LazyResult[dict[str, str]]:
    resolve_input = _build_versioned_node_metadata_resolve_input(
        txn,
        context_refs=context_refs,
        materialization=_versioned_lazy_materialization_policy(txn),
        object_ids=object_ids,
        candidate_models=candidate_models,
        graph_id=graph_id,
        context="resolve_type_names_lazy",
    )
    if resolve_input is None:
        return LazyResult.of({})
    plan = txn._get_transaction_plan_lazy()
    rows_ref = ServerPlanRefId(plan._next_ref())
    txn._add_intent(
        versioned_query_steps.VersionedResolveTypeMapStep(
            rows_ref,
            _build_versioned_resolve_type_map_config(resolve_input),
        ),
    )
    return txn._add_intent(
        VersionedTypeNameMapStep(
            ServerPlanRefId(plan._next_ref()),
            source_ref=rows_ref,
        ),
    )


