        distinct=False,
        joins=[],
        filters=filters,
        order_by=[],
        limit=1 if object_id is not None else None,
        offset=None,
        group_by=[],
        aggregations=[],
        having=[],
        window_functions=[],
        include_deleted=include_deleted,
        type_filter_types=type_filter_types,
        type_filter_column="type_name" if type_filter_types is not None else None,
    )


