) -> list[str]:
    return list(normalize_raw_field_names(model_cls, columns, db_column_source))


@pure_lazy
def _raw_rows_with_model_defaults(
    model_cls: type[DatabaseObjectRow],
    field_names: Sequence[str],
    rows: Sequence[Sequence[object]],
) -> tuple[tuple[str, ...], tuple[tuple[object, ...], ...]]:
    """Add declared model defaults omitted by a raw versioned insert."""
    completed_field_names = list(field_names)
    default_field_names: list[str] = []
    data_field_names, _db_columns = intent_versioning_extended._collect_versioned_batch_data_columns(
        model_cls,
    )
    for field_name in data_field_names:
        if field_name in completed_field_names or field_name in {"sys_id", "created_at", "updated_at"}:
            continue
        field_info = model_cls.model_fields.get(field_name)
        if field_info is not None and field_info.get_default(call_default_factory=False) is not PydanticUndefined:
            default_field_names.append(field_name)
    completed_field_names.extend(default_field_names)
    completed_rows = tuple(
        (
            *tuple(row),
            *(model_cls.model_fields[field_name].get_default(call_default_factory=True) for field_name in default_field_names),
        )
        for row in rows
    )
    return tuple(completed_field_names), completed_rows


@pure_lazy
def _instance_rows_for_versioned_key_many[T: DatabaseObjectRow](
    model_cls: type[T],
    instances: Sequence[T],
    key_field_names: Sequence[str],
) -> tuple[list[str], list[tuple[Any, ...]], tuple[SqlColumnName, ...]]:
    versioning_fields = {"branch_id", "revision_id", "staged_commit_id", "deleted"}
    source_field_names: list[str] = []
    for key_name in key_field_names:
        if key_name not in source_field_names:
            source_field_names.append(key_name)
    field_sources = [model_cls, *(type(instance) for instance in instances)]
    for field_source in field_sources:
        for field_name, field_info in field_source.model_fields.items():
            if field_name in versioning_fields:
                continue
            if is_derived_column(field_info):
                continue
            if field_name not in source_field_names:
                source_field_names.append(field_name)

    def _source_value(instance: T, field_name: str) -> object:
        value = getattr(instance, field_name, None)
        if field_name == "type_name" and value is None:
            return canonical_polymorphic_type_name(type(instance))
        if isinstance(value, BaseModel):
            return value.model_dump(mode="json")
        return value

    rows = [tuple(_source_value(instance, field_name) for field_name in source_field_names) for instance in instances]
    source_db_columns = _instance_db_columns_for_versioned_key_many(
        model_cls,
        instances,
        source_field_names,
    )
    return source_field_names, rows, source_db_columns


@pure_lazy
def _instance_db_columns_for_versioned_key_many[T: DatabaseObjectRow](
    model_cls: type[T],
    instances: Sequence[T],
    source_field_names: Sequence[str],
) -> tuple[SqlColumnName, ...]:
    """Resolve each source field through the concrete model that declares it."""
    field_sources = tuple(
        dict.fromkeys((model_cls, *(type(instance) for instance in instances))),
    )
    db_columns: list[SqlColumnName] = []
    for field_name in source_field_names:
        declaring_models = tuple(field_source for field_source in field_sources if field_name in field_source.model_fields)
        if not declaring_models:
            msg = f"No model in the {model_cls.__name__} family declares field {field_name!r}"
            raise ValueError(msg)
        candidate_columns = {get_db_column_name(field_source, DynamicFieldName(field_name)) for field_source in declaring_models}
        if len(candidate_columns) != 1:
            model_names = ", ".join(model.__name__ for model in declaring_models)
            msg = (
                f"Field {field_name!r} maps to conflicting database columns "
                f"{sorted(str(column) for column in candidate_columns)!r} across "
                f"models [{model_names}]"
            )
            raise ValueError(msg)
        db_columns.append(next(iter(candidate_columns)))
    return tuple(db_columns)


@pure_lazy
def _instance_rows_for_versioned_raw_insert_many[T: DatabaseObjectRow](
    model_cls: type[T],
    instances: Sequence[T],
) -> tuple[list[str], list[tuple[Any, ...]]]:
    source_field_names, source_rows, _source_db_columns = _instance_rows_for_versioned_key_many(model_cls, instances, ())
    if (
        "type_name" in collect_polymorphic_fields(model_cls)
        and collect_polymorphic_type_names(model_cls)
        and "type_name" not in source_field_names
    ):
        source_field_names = [*source_field_names, "type_name"]
        type_name = canonical_polymorphic_type_name(model_cls)
        source_rows = [(*row, type_name) for row in source_rows]
    return source_field_names, source_rows


@pure_lazy
def _publish_versioned_dml_user_id(
    plan: _VersionedDmlUserIdPlan,
    session_id_raw: str | SessionId,
    *,
    after_refs: frozenset[ServerPlanRefId] = frozenset(),
) -> _VersionedDmlUserIdPublication:
    from l4000_permissions.permission_enforcement import is_system_or_schema_session

    session_id = session_id_raw if isinstance(session_id_raw, SessionId) else SessionId(session_id_raw)
    if is_system_or_schema_session(session_id.unwrap_to_sql()):
        return _VersionedDmlUserIdPublication(
            ref_id=ServerPlanRefId("__system_session_permission_user_ref"),
            permission_action_enabled=False,
        )

    from impl.common.l2070_server_plan.steps.session_user_id import SessionUserIdStep

    user_id_ref = ServerPlanRefId(plan._next_ref())
    plan.add_step(
        SessionUserIdStep(
            user_id_ref,
            ServerRefs.scalar(session_id),
            after_refs=after_refs,
        ),
    )
    return _VersionedDmlUserIdPublication(
        ref_id=user_id_ref,
        permission_action_enabled=True,
    )


@pure_lazy
def _ensure_versioned_staged_commit_id[T: VersionedObjectRow](
    instance: T,
    staged_commit_id: StagedCommitId,
) -> T:
    if instance.staged_commit_id is not None:
        return instance
    updated_instance = instance.model_copy(update={"staged_commit_id": staged_commit_id})
    if not isinstance(updated_instance, type(instance)):
        msg = f"model_copy returned unexpected type: {type(updated_instance)!r}"
        raise TypeError(msg)
    return updated_instance


@pure_lazy
def register_precommit_validation_lazy[ValidationT](
    txn: VersionedWriteTransactionLazyMixin,
    validation: LazyResult[ValidationT],
) -> LazyResult[ValidationT]:
    """Register a SQL assertion in the versioned commit validation region."""
    shape = inspect_server_value_shape_for_planning(
        validation,
        site="versioned precommit validation",
    )
    if shape.symbolic_ref_id is None:
        raise ValueError("Versioned precommit validation must publish a plan-owned reference")
    txn.register_precommit_validation_ref(ServerPlanRefId(shape.symbolic_ref_id))
    return validation


class VersionedWriteTransactionLazyMixin(VersionedWritePlanTarget, WriteTransactionLazyMixin):  # pyright: ignore[reportUntypedBaseClass]
    """Lazy methods for SyncVersionedWriteTransaction CRUD."""

    _staged_commit_id: StagedCommitId | None
    _branch_published: bool
    _speculative_publish_fact_store: _ConnectionSpeculativePublishFactStore
    _precommit_validation_refs: frozenset[ServerPlanRefId]
    _speculative_named_branch_scope: _NamedSpeculativeBranchScope | None = None

    @property
    def _versioned_speculative_publish_facts(
        self: VersionedWriteTransactionLazyMixin,
    ) -> Mapping[_ConnectionSpeculativePublishKey, _ConnectionSpeculativePublishFacts]:
        """Return a read-only durable snapshot for diagnostics."""
        txn = cast(_VersionedWriteTxnState, self)
        return MappingProxyType(dict(txn._speculative_publish_fact_store.snapshot(lifecycle="durable")))

    @_versioned_speculative_publish_facts.setter
    def _versioned_speculative_publish_facts(
        self: VersionedWriteTransactionLazyMixin,
        value: dict[object, object],
    ) -> None:
        current_store = getattr(self, "_speculative_publish_fact_store", None)
        pending = {} if current_store is None else dict(current_store.snapshot(lifecycle="pending"))
        self._speculative_publish_fact_store = _ConnectionSpeculativePublishFactStore(value, pending)

    @property
    def _pending_connection_speculative_publish_facts(
        self: VersionedWriteTransactionLazyMixin,
    ) -> Mapping[_ConnectionSpeculativePublishKey, _ConnectionSpeculativePublishFacts]:
        """Return a read-only pending snapshot for diagnostics."""
        txn = cast(_VersionedWriteTxnState, self)
        return MappingProxyType(dict(txn._speculative_publish_fact_store.snapshot(lifecycle="pending")))

    @_pending_connection_speculative_publish_facts.setter
    def _pending_connection_speculative_publish_facts(
        self: VersionedWriteTransactionLazyMixin,
        value: dict[object, object],
    ) -> None:
        current_store = getattr(self, "_speculative_publish_fact_store", None)
        durable = {} if current_store is None else dict(current_store.snapshot(lifecycle="durable"))
        self._speculative_publish_fact_store = _ConnectionSpeculativePublishFactStore(durable, value)

    def register_precommit_validation_ref(
        self: VersionedWriteTransactionLazyMixin,
        ref_id: ServerPlanRefId,
    ) -> None:
        """Require a validation result before this transaction commits."""
        self._precommit_validation_refs = frozenset({*self._precommit_validation_refs, ref_id})

    def _commit_connection_speculative_publish_facts(
        self: VersionedWriteTransactionLazyMixin,
    ) -> None:
        """Promote facts only after the owning database transaction commits.

        Rolled-back writes must not shape later publication SQL. See
        ``docs/design/NER_1381_SPECULATIVE_PUBLICATION_ARCHITECTURE.rst``.
        """
        txn = cast(_VersionedWriteTxnState, self)
        txn._speculative_publish_fact_store.promote(
            staged_commit_id=txn._staged_commit_id,
            resolved_branch=txn._branch_anchor,
        )

    def _restore_connection_speculative_publish_facts(
        self: VersionedWriteTransactionLazyMixin,
    ) -> None:
        """Discard only facts pending in this failed transaction."""
        txn = cast(_VersionedWriteTxnState, self)
        txn._speculative_publish_fact_store.discard_pending(
            staged_commit_id=txn._staged_commit_id,
        )

    @pure_lazy
    def _has_pending_symbolic_speculative_publish_scope(
        self: VersionedWriteTransactionLazyMixin,
    ) -> bool:
        txn = cast(_VersionedWriteTxnState, self)
        return txn._speculative_publish_fact_store.has_pending_symbolic_scope(
            txn._staged_commit_id,
        )

    @pure_lazy
    def _checked_speculative_named_branch_scope(
        self: VersionedWriteTransactionLazyMixin,
    ) -> _NamedSpeculativeBranchScope | None:
        scope = self._speculative_named_branch_scope
        if scope is not None and not isinstance(scope, _NamedSpeculativeBranchScope):
            raise TypeError("Invalid named speculative branch scope: expected a typed branch locator")
        return scope

    def versioned_transaction_planning_snapshot(
        self: VersionedWriteTransactionLazyMixin,
    ) -> VersionedTransactionPlanningSnapshot:
        txn = cast(_VersionedWriteTxnState, self)
        base_revision_id = txn.base_revision_id
        context_refs = get_versioned_lazy_context_refs(self)
        revision_ref = versioned_lazy_context_revision_ref(
            context_refs,
            context=DiagnosticLabel("versioned planning snapshot revision context"),
        )
        bound_context_refs = VersionedLazyContextRefs(
            branch=versioned_lazy_context_branch_ref(
                context_refs,
                context=DiagnosticLabel("versioned planning snapshot branch context"),
            ),
            revision=UNSET if revision_ref is None else revision_ref,
            workspace=context_refs.workspace,
        )

        def _staging_context_factory(
            model_cls: type[DatabaseObjectRow[SysId]],
        ) -> intent_transaction.VersionedStagingCtx:
            return self._get_versioned_staging_context(model_cls, context_refs=bound_context_refs)

        return VersionedTransactionPlanningSnapshot(
            branch_tip_materialization=txn._branch_tip_materialization,
            lazy_revision=txn._lazy_revision,
            lazy_branch=txn._lazy_branch,
            explicit_base_revision_id=txn._explicit_base_revision_id,
            base_revision_id=base_revision_id,
            revision_id=base_revision_id,
            domain=txn.domain,
            staging_context_factory=_staging_context_factory,
            touched_versioned_tables=frozenset(txn._inline_touched_versioned_tables),
        )

    def _mark_commit_branch_touched_model_lazy(
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[DatabaseObjectRow[SysId]],
        *,
        operation: _ConnectionSpeculativeOperation | None = None,
    ) -> None:
        self._mark_commit_branch_touched_table_name_lazy(get_table_name(model_cls), operation=operation)

    def _mark_commit_branch_touched_table_name_lazy(
        self: VersionedWriteTransactionLazyMixin,
        table_name: SqlTableName,
        *,
        operation: _ConnectionSpeculativeOperation | None = None,
    ) -> None:
        if not table_name:
            raise ValueError("Versioned publication facts require a non-empty table name")
        txn = cast(_VersionedWriteTxnState, self)
        txn._inline_touched_versioned_tables.add(table_name)
        self._record_connection_speculative_publish_table_lazy(table_name, operation=operation)

    @pure_lazy
    def _connection_speculative_publish_prefix(
        self: VersionedWriteTransactionLazyMixin,
    ) -> _ConnectionSpeculativePublishPrefix | None:
        txn = cast(_VersionedWriteTxnState, self)
        branch = txn._lazy_branch if txn._branch_anchor is None else txn._branch_anchor
        branch_id: BranchId | BranchScopeToken
        if isinstance(branch, BranchId):
            branch_id = branch
        elif isinstance(branch, ScalarServerRef):
            branch_id = opaque_scope_token(branch)
            branch_ref_id = branch.ref_id
            if branch_ref_id is not None:
                found_seed, seed_value = read_seeded_constant_from_ctx(None, ServerPlanRefId(branch_ref_id))
                if found_seed:
                    if not isinstance(seed_value, BranchId):
                        raise TypeError("Speculative publication scope requires a typed seeded branch ID")
                    branch_id = seed_value
        else:
            return None
        connection_id = txn._connection_id
        if not isinstance(connection_id, ConnectionId):
            raise TypeError("Speculative publication scope requires a typed connection ID")
        domain = txn.domain
        domain_name = domain.name
        return _ConnectionSpeculativePublishPrefix(
            domain_name=_VersioningDomainName(str(domain_name)),
            branch_id=branch_id,
            connection_id=connection_id,
        )

    @pure_lazy
    def _connection_speculative_publish_key(
        self: VersionedWriteTransactionLazyMixin,
    ) -> _ConnectionSpeculativePublishKey | None:
        prefix = self._connection_speculative_publish_prefix()
        if prefix is None:
            return None
        staged_commit_id = cast(_VersionedWriteTxnState, self)._staged_commit_id
        if not isinstance(staged_commit_id, StagedCommitId):
            raise RuntimeError("Speculative publication scope requires a typed staged-commit ID")
        return _ConnectionSpeculativePublishKey(
            prefix=prefix,
            staged_commit_id=staged_commit_id,
        )

    @pure_lazy
    def _connection_speculative_publish_facts(
        self: VersionedWriteTransactionLazyMixin,
        *,
        all_connections: bool = False,
    ) -> _ConnectionSpeculativePublishFacts | None:
        prefix = self._connection_speculative_publish_prefix()
        if prefix is None:
            return None
        txn = cast(_VersionedWriteTxnState, self)
        durable_snapshot = txn._speculative_publish_fact_store.snapshot(lifecycle="durable")
        pending_snapshot = txn._speculative_publish_fact_store.snapshot(lifecycle="pending")

        named_scope = self._checked_speculative_named_branch_scope()

        def _matches_scope(
            key: _ConnectionSpeculativePublishKey,
            facts: _ConnectionSpeculativePublishFacts,
        ) -> bool:
            if (
                isinstance(prefix.branch_id, BranchScopeToken)
                and named_scope is not None
                and named_scope in facts.named_branch_scopes
                and key.prefix.domain_name == prefix.domain_name
                and (all_connections or key.prefix.connection_id == prefix.connection_id)
            ):
                return True
            if (
                isinstance(key.prefix.branch_id, BranchScopeToken)
                and isinstance(txn._lazy_branch, ScalarServerRef)
                and key.prefix.branch_id == opaque_scope_token(txn._lazy_branch)
                and key.staged_commit_id == txn._staged_commit_id
                and key.prefix.domain_name == prefix.domain_name
                and key.prefix.connection_id == prefix.connection_id
            ):
                return True
            if not all_connections:
                return key.prefix == prefix
            return key.prefix.domain_name == prefix.domain_name and key.prefix.branch_id == prefix.branch_id

        sources = tuple(
            facts for snapshot in (durable_snapshot, pending_snapshot) for key, facts in snapshot if _matches_scope(key, facts)
        )
        if not sources:
            return None
        if len(sources) == 1:
            return sources[0]
        combined = _ConnectionSpeculativePublishFacts()
        for facts in sources:
            combined = combined.merged_with(facts)
        return combined

    def _set_speculative_named_branch_scope(
        self: VersionedWriteTransactionLazyMixin,
        branch_name: BranchName,
        workspace_id: WorkspaceId,
    ) -> None:
        """Retain a locator for speculative hints, never for branch authority."""
        self._speculative_named_branch_scope = _NamedSpeculativeBranchScope(
            branch_name=branch_name,
            workspace_id=workspace_id,
        )

    def _record_connection_speculative_publish_table_lazy(
        self: VersionedWriteTransactionLazyMixin,
        table_name: SqlTableName,
        *,
        operation: _ConnectionSpeculativeOperation | None,
    ) -> None:
        txn = cast(_VersionedWriteTxnState, self)
        named_scope = self._checked_speculative_named_branch_scope()
        staged_commit_id = txn._ensure_staged_commit_id()
        key = self._connection_speculative_publish_key()
        if key is None:
            return
        del staged_commit_id
        txn._speculative_publish_fact_store.record(
            key,
            table_name=SqlTableName(table_name),
            operation=operation,
            named_scope=named_scope,
            insert_only_downgraded=txn._versioned_speculative_insert_only_downgraded,
        )

    def _discard_connection_speculative_publish_fact_keys(
        self: VersionedWriteTransactionLazyMixin,
        keys: frozenset[_ConnectionSpeculativePublishKey],
    ) -> None:
        txn = cast(_VersionedWriteTxnState, self)
        txn._speculative_publish_fact_store.discard(keys=keys)

    def _replace_exact_connection_speculative_publish_facts(
        self: VersionedWriteTransactionLazyMixin,
        selected_staged_commit_ids: tuple[StagedCommitId, ...],
        *,
        touched_table_names: frozenset[SqlTableName],
        non_insert_table_names: frozenset[SqlTableName],
        deleted_table_names: frozenset[SqlTableName],
    ) -> None:
        """Replace known selected scopes with facts from authoritative SQL evidence."""
        selected_ids = _require_authoritative_speculative_fact_sets_lazy(
            selected_staged_commit_ids,
            touched_table_names=touched_table_names,
            non_insert_table_names=non_insert_table_names,
            deleted_table_names=deleted_table_names,
        )
        txn = cast(_VersionedWriteTxnState, self)
        txn._speculative_publish_fact_store.replace(
            selected_staged_commit_ids=selected_ids,
            touched_table_names=touched_table_names,
            non_insert_table_names=non_insert_table_names,
            deleted_table_names=deleted_table_names,
        )

    def _record_missing_connection_scoped_speculative_publish_facts(
        self: VersionedWriteTransactionLazyMixin,
        selected_staged_commit_ids: tuple[StagedCommitId, ...],
        *,
        touched_table_names: frozenset[SqlTableName],
        non_insert_table_names: frozenset[SqlTableName],
        deleted_table_names: frozenset[SqlTableName],
    ) -> None:
        """Record selected scopes that the current logical connection owns."""
        selected_ids = _require_authoritative_speculative_fact_sets_lazy(
            selected_staged_commit_ids,
            touched_table_names=touched_table_names,
            non_insert_table_names=non_insert_table_names,
            deleted_table_names=deleted_table_names,
        )
        txn = cast(_VersionedWriteTxnState, self)
        txn._speculative_publish_fact_store.record_missing(
            prefix=self._connection_speculative_publish_prefix(),
            selected_staged_commit_ids=selected_ids,
            touched_table_names=touched_table_names,
            non_insert_table_names=non_insert_table_names,
            deleted_table_names=deleted_table_names,
            named_scope=self._checked_speculative_named_branch_scope(),
        )

    def _consume_exact_connection_speculative_publish_facts(
        self: VersionedWriteTransactionLazyMixin,
        selected_staged_commit_ids: tuple[StagedCommitId, ...],
    ) -> None:
        """Discard facts for the exact selected staged scopes."""
        selected_ids = frozenset(selected_staged_commit_ids)
        txn = cast(_VersionedWriteTxnState, self)
        keys = frozenset(
            key for key, _facts in txn._speculative_publish_fact_store.all_snapshots() if key.staged_commit_id in selected_ids
        )
        self._discard_connection_speculative_publish_fact_keys(keys)

    def _consume_all_connection_speculative_publish_facts(
        self: VersionedWriteTransactionLazyMixin,
    ) -> None:
        """Discard all facts for the current branch and logical connection."""
        txn = cast(_VersionedWriteTxnState, self)
        branch_id = txn._branch_anchor
        if not isinstance(branch_id, BranchId):
            raise RuntimeError("Published speculative facts require a concrete branch scope")
        prefix = _ConnectionSpeculativePublishPrefix(
            domain_name=_VersioningDomainName(txn.domain.name),
            branch_id=branch_id,
            connection_id=txn._connection_id,
        )
        keys = frozenset(
            key
            for key, _facts in txn._speculative_publish_fact_store.all_snapshots()
            if key.prefix == prefix
            or (
                isinstance(key.prefix.branch_id, BranchScopeToken)
                and isinstance(txn._lazy_branch, ScalarServerRef)
                and key.prefix.branch_id == opaque_scope_token(txn._lazy_branch)
                and key.staged_commit_id == txn._staged_commit_id
                and key.prefix.domain_name == prefix.domain_name
                and key.prefix.connection_id == prefix.connection_id
            )
        )
        self._discard_connection_speculative_publish_fact_keys(keys)

    @pure_lazy
    def _connection_speculative_publish_log_snapshot(
        self: VersionedWriteTransactionLazyMixin,
    ) -> dict[str, object]:
        facts = self._connection_speculative_publish_facts()
        key = self._connection_speculative_publish_prefix()
        if facts is None:
            return {
                "key": key,
                "available": False,
                "touched_tables": (),
                "non_insert_tables": (),
                "deleted_tables": (),
                "insert_only_tables": (),
            }
        return {
            "key": key,
            "available": True,
            "touched_tables": tuple(sorted(facts.touched_tables)),
            "non_insert_tables": tuple(sorted(facts.non_insert_tables)),
            "deleted_tables": tuple(sorted(facts.deleted_tables)),
            "insert_only_tables": tuple(sorted(facts.insert_only_tables)),
        }

    @pure_lazy
    def _connection_speculative_publish_table_names(
        self: VersionedWriteTransactionLazyMixin,
        *,
        all_connections: bool = False,
    ) -> set[SqlTableName] | None:
        """Return physical-connection-owned speculative state for the selected scope."""
        facts = self._connection_speculative_publish_facts(all_connections=all_connections)
        if facts is None:
            return None
        return set(facts.touched_tables)

    @pure_lazy
    def _connection_speculative_non_insert_table_names(
        self: VersionedWriteTransactionLazyMixin,
        *,
        all_connections: bool = False,
    ) -> set[SqlTableName] | None:
        facts = self._connection_speculative_publish_facts(all_connections=all_connections)
        if facts is None:
            return None
        return set(facts.non_insert_tables)

    @pure_lazy
    def _connection_speculative_deleted_table_names(
        self: VersionedWriteTransactionLazyMixin,
        *,
        all_connections: bool = False,
    ) -> set[SqlTableName] | None:
        facts = self._connection_speculative_publish_facts(all_connections=all_connections)
        if facts is None:
            return None
        return set(facts.deleted_tables)

    @pure_lazy
    def _connection_speculative_insert_only_table_names(
        self: VersionedWriteTransactionLazyMixin,
        *,
        all_connections: bool = False,
    ) -> set[SqlTableName] | None:
        facts = self._connection_speculative_publish_facts(all_connections=all_connections)
        if facts is None:
            return None
        return set(facts.insert_only_tables)

    def _mark_commit_branch_delete_side_effect_tables_lazy(
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[DatabaseObjectRow[SysId]],
    ) -> None:
        from impl.common.l7100_versioned_operations.fk_cascade import get_fk_map

        self._mark_commit_branch_touched_model_lazy(model_cls, operation="delete")
        txn = cast(_VersionedWriteTxnState, self)
        deleted_tables = txn._inline_deleted_versioned_tables
        deleted_tables.add(get_table_name(model_cls))
        domain = cast(_VersionedWriteTxnState, self).domain
        fk_map = get_fk_map(domain)
        # Expand the touched set through producer-declared CASCADE and SET NULL
        # relationships without publishing unrelated domain tables.
        seen: set[type[DatabaseObjectRow[SysId]]] = set()
        pending: list[type[DatabaseObjectRow[SysId]]] = [model_cls]
        while pending:
            parent_model = pending.pop()
            if parent_model in seen:
                continue
            seen.add(parent_model)
            parent_table = get_table_name(parent_model)
            for _key_model, relationships in fk_map.items():
                for relationship in relationships:
                    if get_table_name(relationship.parent_model) != parent_table:
                        continue
                    on_delete = relationship.on_delete.upper().replace(" ", "_")
                    if on_delete not in {"CASCADE", "SET_NULL"}:
                        continue
                    child_model_cast = cast("type[DatabaseObjectRow[SysId]]", relationship.child_model)
                    child_operation: _ConnectionSpeculativeOperation = "delete" if on_delete == "CASCADE" else "update"

                    self._mark_commit_branch_touched_model_lazy(
                        child_model_cast,
                        operation=child_operation,
                    )
                    if on_delete == "CASCADE":
                        deleted_tables.add(get_table_name(child_model_cast))
                        pending.append(child_model_cast)

    def _has_pending_versioned_writes_for_plan(
        self: VersionedWriteTransactionLazyMixin,
    ) -> bool:
        snapshot = self.versioned_transaction_planning_snapshot()
        return bool(snapshot.touched_versioned_tables)

    def _speculative_publish_table_names_hint(
        self: VersionedWriteTransactionLazyMixin,
    ) -> frozenset[str]:
        """Return the SQL-checked publish hint for staged writes known to this transaction."""

        pending_refs = self._flush_pending_lazy_ops_to_plan()
        del pending_refs
        snapshot = self.versioned_transaction_planning_snapshot()
        touched_tables = set(snapshot.touched_versioned_tables)
        touched_tables.update(self._plan_staging_table_names_hint())
        txn = cast(_VersionedWriteTxnState, self)
        deleted_tables = set(txn._inline_deleted_versioned_tables)
        touched_tables.update(deleted_tables)
        if not touched_tables:
            return frozenset()
        return frozenset(touched_tables)

    @pure_lazy
    def _plan_staging_table_names_hint(self: VersionedWriteTransactionLazyMixin) -> set[SqlTableName]:
        """Return versioned base tables with staging contexts already present in the lazy plan."""

        txn = cast(_VersionedWriteTxnState, self)
        domain_table_names = _txn_domain_versioned_table_names(txn)

        plan = self._get_transaction_plan_lazy()
        staged_to_base = {
            derive_versioned_table_names(VersionedBaseTableName(str(base_table))).staged: base_table for base_table in domain_table_names
        }
        touched_tables: set[SqlTableName] = set()
        for step in plan._steps:
            for raw_table_name in step.tables_written():
                table_name = staged_to_base.get(VersionedStagedTableName(str(raw_table_name)))
                if table_name is not None:
                    touched_tables.add(table_name)
        return touched_tables

    @pure_lazy
    def _expand_speculative_publish_tables_for_side_effects(
        self: VersionedWriteTransactionLazyMixin,
        touched_tables: set[SqlTableName],
    ) -> set[SqlTableName]:
        from impl.common.l7100_versioned_operations.fk_cascade import get_fk_map

        txn = cast(_VersionedWriteTxnState, self)
        domain_table_names = _txn_domain_versioned_table_names(txn)
        child_tables_by_parent: dict[SqlTableName, set[SqlTableName]] = {}
        fk_map = get_fk_map(txn.domain)
        for parent_model, relationships in fk_map.items():
            parent_table = get_table_name(parent_model)
            if parent_table not in domain_table_names:
                continue
            for relationship in relationships:
                on_delete = relationship.on_delete.upper().replace(" ", "_")
                if on_delete not in {"CASCADE", "SET_NULL"}:
                    continue
                child_table = get_table_name(relationship.child_model)
                if child_table not in domain_table_names:
                    continue
                child_tables_by_parent.setdefault(parent_table, set()).add(child_table)

        for graph_definition in txn.domain.graphs:
            graph_member_tables = {
                get_table_name(model_cls) for model_cls in (*graph_definition.node_types, *graph_definition.edge_types)
            }
            if graph_member_tables & touched_tables:
                for graph_table in graph_member_tables:
                    child_tables_by_parent.setdefault(graph_table, set()).update(
                        graph_member_tables - {graph_table},
                    )

        pending = list(touched_tables)
        seen: set[SqlTableName] = set()
        while pending:
            parent_table = pending.pop()
            if parent_table in seen:
                continue
            seen.add(parent_table)
            for child_table in child_tables_by_parent.get(parent_table, ()):
                if child_table in touched_tables:
                    continue
                touched_tables.add(child_table)
                pending.append(child_table)
        return touched_tables

    def _ensure_staged_commit_id(
        self: VersionedWriteTransactionLazyMixin,
    ) -> StagedCommitId:
        """Return the staged commit ID, generating it on first use."""
        txn = cast(_VersionedWriteTxnState, self)
        staged_commit_id = txn._staged_commit_id
        if staged_commit_id is None:
            staged_commit_id = StagedCommitId.new()
            txn._staged_commit_id = staged_commit_id
        return staged_commit_id

    def _staged_commit_id_value(self: VersionedWriteTransactionLazyMixin) -> str:
        """Return the staged commit ID as a SQL-safe string."""
        staged_commit_id = self._ensure_staged_commit_id()
        return staged_commit_id.unwrap_to_str()

    @pure_lazy
    def _check_versioned_or_delegate[T](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
    ) -> bool:
        """Return True if model_cls is versioned."""
        return issubclass(model_cls, VersionedObjectRow)

    @pure_lazy
    def query_lazy[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
    ) -> Any:
        """Query versioned tables through the versioned plan and unversioned tables through the base write transaction."""
        versioned_or_delegate = self._check_versioned_or_delegate(model_cls)
        if not versioned_or_delegate:
            return WriteTransactionLazyMixin.query_lazy(
                cast(Any, cast(_VersionedWriteTxnState, self).base_write_transaction),
                model_cls,
            )
        return _VersionedWriteQueryBuilder(cast(Any, self), cast("type[VersionedObjectRow[SysId]]", model_cls))

    @pure_lazy
    def query_unfiltered_lazy[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        *,
        internal_permission_query_request: InternalPermissionQueryRequest | None = None,
    ) -> Any:
        """Unfiltered query variant with the same versioned routing as ``query_lazy``.

        ``WriteTransactionLazyMixin.query_unfiltered_lazy`` builds a plain
        ``WriteQueryBuilder``, so its read terminals bypass the versioned
        lowering that ``query_lazy`` gets from ``_VersionedWriteQueryBuilder``.
        """
        if not self._check_versioned_or_delegate(model_cls):
            return ReadTransactionLazyMixin.query_unfiltered_lazy(
                cast(Any, cast(_VersionedWriteTxnState, self).base_read_transaction),
                model_cls,
                internal_permission_query_request=internal_permission_query_request,
            )
        builder = _VersionedWriteQueryBuilder(cast(Any, self), cast("type[VersionedObjectRow[SysId]]", model_cls))
        return builder._without_permission_filtering(internal_permission_query_request)

    @pure_lazy
    def _get_versioned_staging_context(
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[DatabaseObjectRow[SysId]],
        *,
        context_refs: VersionedLazyContextRefs,
    ) -> intent_transaction.VersionedStagingCtx:
        """Compute all versioned staging data. Pure — no I/O."""
        txn = cast(_VersionedWriteTxnState, self)
        _require_versioned_model_in_domain(
            txn,
            model_cls,
            operation="versioned staging",
        )
        txn._ensure_staged_commit_id()
        lazy_branch = versioned_lazy_context_branch_ref(
            context_refs,
            context=DiagnosticLabel("_get_versioned_staging_context branch context"),
        )
        _require_versioned_publication_state(
            txn,
            plan=txn._get_transaction_plan_lazy(),
        )
        lazy_revision = versioned_lazy_context_revision_ref(
            context_refs,
            context=DiagnosticLabel("_get_versioned_staging_context revision context"),
        )
        literal_branch_anchor = versioned_lazy_context_literal_branch(context_refs)
        branch_scope_token = txn._branch_scope_token
        staged_commit_id_raw = txn._staged_commit_id_value()

        backend = versioned_backend_registry_module.versioned_backend_registry.get("sparse", self)
        # Register subtype fields so auxiliary models include them
        physical = backend._get_physical_table_model(model_cls)
        backend._register_polymorphic_fields(physical, model_cls)
        staged_model = backend._get_or_create_staged_model(model_cls)
        tip_model = backend._get_or_create_tip_model(model_cls)

        common_columns = physical_data_db_columns_staged_tip_intersection(staged_model, tip_model)

        # Polymorphic discriminator names
        raw_type_names = collect_polymorphic_type_names(model_cls)
        type_ids: list[str] | None = list(raw_type_names) if raw_type_names else None

        conn_id_raw = txn.connection_id.unwrap_to_uuid_compatible_str()
        sess_id_raw = txn.session_id.unwrap_to_sql()
        domain = txn.domain

        staging_ctx = intent_transaction.VersionedStagingCtx(
            staged_model=staged_model,
            tip_model=tip_model,
            common_columns=common_columns,
            type_ids=type_ids,
            lazy_branch=lazy_branch,
            lazy_revision=lazy_revision,
            branch_tip_materialization=_versioned_lazy_materialization_policy(txn).tip_materialization,
            staged_commit_id_raw=staged_commit_id_raw,
            domain=domain,
            connection_id_raw=conn_id_raw,
            session_id_raw=sess_id_raw,
            staged_visibility=txn._staged_visibility,
            branch_scope_token=branch_scope_token,
            literal_branch=literal_branch_anchor,
            sparse_table_name_value=SqlTableName(
                derive_versioned_table_names(VersionedBaseTableName(str(get_table_name(model_cls)))).sparse
            ),
        )
        txn._inline_touched_versioned_tables.add(SqlTableName(get_table_name(model_cls)))
        return staging_ctx

    @pure_lazy
    def _prepare_versioned_instance[T: VersionedObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        instance: T,
        staging_ctx: intent_transaction.VersionedStagingCtx,
    ) -> T:
        """Prepare instance for versioned staging. Pure — no I/O."""
        prepared_obj = _prepare_instance.prepare_instance_for_insert_lazy(model_cls, instance)
        if not isinstance(prepared_obj, model_cls):
            msg = f"prepare_instance_for_insert_lazy returned unexpected type: {type(prepared_obj)!r}"
            raise TypeError(msg)
        prepared: T = prepared_obj
        txn = cast(_VersionedWriteTxnState, self)
        prepared = _inject_trust_defaults(
            _trust_shape_for_model(self, model_cls),
            prepared,
            txn.session_id,
        )
        return _ensure_versioned_staged_commit_id(
            prepared,
            StagedCommitId(staging_ctx.staged_commit_id_raw),
        )

