    # ── Insert ──

    @pure_lazy
    def insert_lazy[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        instance: LazyResult[T],
        *,
        after_refs: Sequence[ServerPlanRefId] = (),
    ) -> LazyResult[T]:
        """Versioned insert via VersionedInsertIntent. Pure — no I/O.

        ``instance`` is ``LazyResult[T]``. For user-constructed objects,
        use ``LazyResult.of(MyModel(...))``. The literal value is read only
        from the Python-side lazy container; no SQL-derived value is inspected
        during planning.
        """
        if not self._check_versioned_or_delegate(model_cls):
            return WriteTransactionLazyMixin.insert_lazy(
                cast(Any, self),
                model_cls,
                instance,
                after_refs=after_refs,
            )

        permission_context_ref, permission_context_type = _versioned_permission_context(
            self,
            model_cls,
        )
        self._mark_commit_branch_touched_model_lazy(cast("type[DatabaseObjectRow[SysId]]", model_cls), operation="insert")
        context_refs = get_versioned_lazy_context_refs(self)
        sc = self._get_versioned_staging_context(model_cls, context_refs=context_refs)
        plan = self._get_transaction_plan_lazy()
        source_ref = _published_lazy_ref_id(instance, context="insert_lazy instance")
        concrete_instance = None if source_ref is not None else _require_concrete_lazy_input(instance, context="insert_lazy instance")
        if concrete_instance is not None:
            _validate_concrete_graph_edge_self_loop(
                cast("type[DatabaseObjectRow[SysId]]", model_cls),
                cast("DatabaseObjectRow[SysId]", concrete_instance),
            )
            concrete_instance = _inject_trust_defaults(
                _trust_shape_for_model(self, model_cls),
                concrete_instance,
                cast(Any, self).session_id,
            )
        versioned_insert_inputs = (
            None
            if concrete_instance is None
            else intent_versioning_extended._shape_versioned_insert_intent_inputs(
                model_cls,
                concrete_instance,
                sc,
                cast(ObjectServerRef[T], LazyBuilderContext(plan).ref_for(concrete_instance)),
                after_refs=frozenset(after_refs),
                permission_context_ref=permission_context_ref,
                permission_context_type=permission_context_type,
            )
        )
        if concrete_instance is not None:
            assert versioned_insert_inputs is not None
            versioned_source, versioned_config = versioned_insert_inputs
            return _record_versioned_write_tail(
                self,
                self._add_intent(
                    intent_versioning_extended.VersionedInsertIntent(
                        ref_id=ServerPlanRefId(plan._next_ref()),
                        model_cls=model_cls,
                        instance=versioned_source,
                        config=cast(
                            "ScalarServerRef[Any]",
                            LazyBuilderContext(plan).ref_for(versioned_config),
                        ),
                    ),
                ),
                context="insert_lazy versioned insert",
            )
        assert source_ref is not None
        return _record_versioned_write_tail(
            self,
            self._add_intent(
                intent_versioning_extended.VersionedInsertDeferredIntent(
                    ref_id=ServerPlanRefId(plan._next_ref()),
                    model_cls=model_cls,
                    instance=ServerRefs.from_ref_id(
                        ServerPlanRefId(source_ref),
                        variant="object",
                    ),
                    config=intent_versioning_extended._VersionedInsertDeferredIntentConfig(
                        staging_ctx=sc,
                        after_refs=frozenset(after_refs),
                        dependency_only=intent_versioning_extended.VersionedDependencyOnlyFlag(False),
                    ),
                ),
            ),
            context="insert_lazy deferred versioned insert",
        )

    @pure_lazy
    def insert_dependency_ref[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        instance: LazyResult[T],
        *,
        after_refs: Sequence[ServerPlanRefId] = (),
    ) -> ObjectServerRef[T]:
        """Add a versioned insert and return only its dependency ref."""
        if not self._check_versioned_or_delegate(model_cls):
