    @pure_lazy
    def insert_many_lazy[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        instances: Sequence[T] | LazyResult[Sequence[T]] | LazyResult[list[T]] | LazyResult[tuple[T, ...]] | ObjectSequenceServerRef[T],
        *,
        after_refs: Sequence[ServerPlanRefId] = (),
    ) -> LazyResult[list[T]]:
        """Versioned insert many: single bulk intent for all instances."""
        source = normalize_object_sequence_input(instances, context="insert_many_lazy instances")
        concrete_list = source.literal_values
        if concrete_list is not None and not concrete_list:
            return LazyResult.of([])

        if not self._check_versioned_or_delegate(model_cls):
            if after_refs:
                msg = "insert_many_lazy after_refs require a versioned model"
                raise TypeError(msg)
            if source.source_ref_id is not None:
                plan = self._get_transaction_plan_lazy()
                _check_write_permission_lazy(self, model_cls)
                return self._add_intent(
                    intent_crud.InsertManyDeferredIntent(
                        ref_id=ServerPlanRefId(plan._next_ref()),
                        model_cls=model_cls,
                        instances=ServerRefs.from_ref_id(
                            source.source_ref_id,
                            variant="object_sequence",
                        ),
                    ),
                )
            assert concrete_list is not None
            return WriteTransactionLazyMixin.insert_many_lazy(
                cast(Any, cast(_VersionedWriteTxnState, self).base_write_transaction),
                model_cls,
                concrete_list,
            )

        self._mark_commit_branch_touched_model_lazy(
            cast("type[DatabaseObjectRow[SysId]]", model_cls),
            operation="insert",
        )
        context_refs = get_versioned_lazy_context_refs(self)
        sc = self._get_versioned_staging_context(model_cls, context_refs=context_refs)
        assert issubclass(model_cls, VersionedObjectRow)
        v_model = cast(type[VersionedObjectRow], model_cls)
        plan = self._get_transaction_plan_lazy()
        prepared_list: tuple[T, ...] | None = None
        if concrete_list is not None:
            prepared_instances: list[T] = []
            for instance in concrete_list:
                concrete_model_cls = type(instance)
                if not issubclass(concrete_model_cls, v_model):
                    msg = f"insert_many instance type {concrete_model_cls.__name__} is not a subtype of {v_model.__name__}"
                    raise TypeError(msg)
                prepared_instances.append(
                    cast(
                        T,
                        self._prepare_versioned_instance(
                            concrete_model_cls,
                            cast(VersionedObjectRow, instance),
                            sc,
                        ),
                    ),
                )
            prepared_list = tuple(prepared_instances)
            backend = versioned_backend_registry_module.versioned_backend_registry.get(
                "sparse",
                self,
            )
            grouped_instances: dict[type[DatabaseObjectRow[Any]], list[T]] = {}
            requested_table = get_table_name(model_cls)
            for instance in prepared_list:
                concrete_model = type(instance)
                physical_model = (
                    model_cls if get_table_name(concrete_model) == requested_table else backend._get_physical_table_model(concrete_model)
                )
                grouped_instances.setdefault(physical_model, []).append(instance)

            raw_deleted_by_model = getattr(
                self,
                "_versioned_literal_delete_ids_by_model",
                {},
            )
            assert isinstance(raw_deleted_by_model, dict)
            deleted_by_model = dict(raw_deleted_by_model)
            dependency_refs: list[ServerPlanRefId] = []
            previous_ref: ServerPlanRefId | None = None
            for physical_model, group in grouped_instances.items():
                model_key = cast("type[DatabaseObjectRow[SysId]]", physical_model)
                current_insert_ids = {str(instance.sys_id) for instance in group}
                deleted_ids = set(deleted_by_model.get(model_key, set()))
                deleted_ids.difference_update(current_insert_ids)
                deleted_by_model[model_key] = deleted_ids
                if get_large_column_configs(physical_model):
                    for instance in group:
                        concrete_model = type(instance)
                        inserted = self.insert_lazy(
                            concrete_model,
                            LazyResult.of(instance),
                            after_refs=((previous_ref,) if previous_ref is not None else tuple(after_refs)),
                        )
                        write_ref = getattr(
                            inserted,
                            "_commit_dependency_ref_id",
                            None,
                        ) or getattr(inserted, "_symbolic_ref_id", None)
                        if write_ref is None:
                            msg = "insert_many_lazy large-column insert did not expose a commit dependency ref"
                            raise RuntimeError(msg)
                        previous_ref = ServerPlanRefId(write_ref)
                        dependency_refs.append(previous_ref)
                    continue
                raw_columns, raw_rows = _instance_rows_for_versioned_raw_insert_many(
                    physical_model,
                    group,
                )
                raw_ref = self.insert_many_raw_lazy(
                    physical_model,
                    raw_columns,
                    raw_rows,
                    db_column_source=physical_model,
                    after_refs=((previous_ref,) if previous_ref is not None else tuple(after_refs)),
                )
                raw_dependency_ref = (
                    getattr(raw_ref, "_commit_dependency_ref_id", None)
                    or getattr(raw_ref, "_symbolic_ref_id", None)
                    or getattr(raw_ref, "_step_ref_id", None)
                )
                if raw_dependency_ref is None:
                    msg = "insert_many_lazy raw staging path did not expose a commit dependency ref"
                    raise RuntimeError(msg)
                previous_ref = ServerPlanRefId(raw_dependency_ref)
                dependency_refs.append(previous_ref)
            object.__setattr__(
                self,
                "_versioned_literal_delete_ids_by_model",
                deleted_by_model,
            )
            published = _static_value_after_refs_lazy(
                self,
                list(prepared_list),
                source_refs=tuple(dependency_refs),
            )
            if previous_ref is not None:
                object.__setattr__(
                    published,
                    "_commit_dependency_ref_id",
                    str(previous_ref),
                )
            return published
        return _record_versioned_write_tail(
            self,
            self._add_intent(
                (
                    intent_versioning_extended.VersionedInsertManyIntent(
                        ref_id=ServerPlanRefId(plan._next_ref()),
                        model_cls=model_cls,
                        instances=ServerRefs.object_sequence(
                            prepared_list,
                        ),
                        config=ServerRefs.scalar(
                            intent_versioning_extended._VersionedInsertManyConfig(
                                staging_ctx=sc,
                                literal_instances=prepared_list,
                                after_refs=frozenset(after_refs),
                            ),
                        ),
                    )
                    if prepared_list is not None
                    else intent_versioning_extended.VersionedInsertManyDeferredIntent(
                        ref_id=ServerPlanRefId(plan._next_ref()),
                        model_cls=model_cls,
                        instances=_require_object_sequence_source_ref(
                            cast(
                                "ObjectSequenceServerRef[DatabaseObjectRow[SysId]]",
                                source.to_ref(),
                            ),
                            context="insert_many_lazy deferred instances",
                        ),
                        config=ServerRefs.scalar(
                            intent_versioning_extended._VersionedInsertManyConfig(
                                staging_ctx=sc,
                                after_refs=frozenset(after_refs),
                            ),
                        ),
                    )
                ),
            ),
            context="insert_many_lazy",
        )

    # ── Update ──

    @pure_lazy
    def update_lazy[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        instance: LazyResult[T],
    ) -> LazyResult[T]:
        """Versioned update = re-stage a row. Pure.

        ``instance`` must be a ``LazyResult[T]`` — either from a prior
        ``select_one_lazy`` (database-derived) or ``LazyResult.of(obj)``
        (user-constructed). The instance flows through the pipeline as
        a SQL reference, not a concrete Python value.
        """
        if not self._check_versioned_or_delegate(model_cls):
            return WriteTransactionLazyMixin.update_lazy(
                cast(Any, cast(_VersionedWriteTxnState, self).base_write_transaction),
                model_cls,
                instance,
            )

        permission_context_ref, permission_context_type = _versioned_permission_context(
            self,
            model_cls,
        )
        self._mark_commit_branch_touched_model_lazy(cast("type[DatabaseObjectRow[SysId]]", model_cls), operation="update")
        plan = self._get_transaction_plan_lazy()
        instance_shape = inspect_server_value_shape_for_planning(
            instance,
            site="update_lazy instance",
        )
        source_ref = None if instance_shape.symbolic_ref_id is None else str(instance_shape.symbolic_ref_id)
        concrete_instance = instance_shape.literal_value if instance_shape.has_literal_value else None
        if concrete_instance is None and source_ref is None:
            concrete_instance = _require_concrete_lazy_input(instance, context="update_lazy instance")
        update_model_cls: type[DatabaseObjectRow] = model_cls
        if concrete_instance is not None and not isinstance(concrete_instance, DatabaseObjectRow):
            raise TypeError("update_lazy literal instance must be a DatabaseObjectRow")
        if concrete_instance is not None:
            concrete_model_cls = type(concrete_instance)
            if concrete_model_cls is not model_cls and issubclass(concrete_model_cls, model_cls):
                update_model_cls = concrete_model_cls
        context_refs = get_versioned_lazy_context_refs(self)
        sc = self._get_versioned_staging_context(
            cast("type[DatabaseObjectRow]", update_model_cls),
            context_refs=context_refs,
        )
        versioned_update_inputs = (
            None
            if concrete_instance is None
            else intent_versioning_extended._shape_versioned_update_intent_inputs(
                cast("type[DatabaseObjectRow]", update_model_cls),
                concrete_instance,
                sc,
                permission_context_ref=permission_context_ref,
                permission_context_type=permission_context_type,
            )
        )
        if concrete_instance is not None:
            assert versioned_update_inputs is not None
            versioned_source, versioned_config = versioned_update_inputs
            return _record_versioned_write_tail(
                self,
                self._add_intent(
                    intent_versioning_extended.VersionedUpdateIntent(
                        ref_id=ServerPlanRefId(plan._next_ref()),
                        model_cls=update_model_cls,
                        source=versioned_source,
                        config=ServerRefs.scalar(versioned_config),
                    ),
                ),
                context="versioned update",
            )
        assert source_ref is not None
        source_producer = next(
            (step for step in plan._steps if step.ref_id == ServerPlanRefId(source_ref)),
            None,
        )
        source_sql_ref = source_producer.raw_payload_source_ref() if source_producer is not None else None
        return _record_versioned_write_tail(
            self,
            self._add_intent(
                intent_versioning_extended.VersionedUpdateDeferredIntent(
                    ref_id=ServerPlanRefId(plan._next_ref()),
                    model_cls=model_cls,
                    source=ServerRefs.from_ref_id(
                        ServerPlanRefId(source_ref),
                        variant="object",
                    ),
                    config=intent_versioning_extended._VersionedUpdateDeferredIntentConfig(
                        staging_ctx=sc,
                        source_value=None,
                        after_refs=frozenset(),
                        source_sql_ref=source_sql_ref,
                    ),
                ),
            ),
            context="deferred versioned update",
        )

    @pure_lazy
    def update_dependency_ref[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        instance: ObjectServerRef[T],
        *,
        literal_instance: T | None = None,
        after_refs: Sequence[ServerPlanRefId] = (),
    ) -> ObjectServerRef[T | None]:
        """Add a versioned update from a ServerRef source and return only its dependency ref."""
        if not self._check_versioned_or_delegate(model_cls):
            base_write_txn = cast(_VersionedWriteTxnState, self).base_write_transaction
            _require_same_lazy_plan_owner(
                self,
                base_write_txn,
                context="update_dependency_ref delegate",
            )
            return WriteTransactionLazyMixin.update_dependency_ref(
                cast(Any, base_write_txn),
                model_cls,
                instance,
                literal_instance=literal_instance,
                after_refs=after_refs,
            )
        self._mark_commit_branch_touched_model_lazy(cast("type[DatabaseObjectRow[SysId]]", model_cls), operation="update")
        context_refs = get_versioned_lazy_context_refs(self)
        sc = self._get_versioned_staging_context(model_cls, context_refs=context_refs)
        plan = self._get_transaction_plan_lazy()
        return cast(
            "ObjectServerRef[T | None]",
            _record_versioned_write_tail_ref(
                self,
                self._add_intent_ref(
                    intent_versioning_extended.VersionedUpdateDeferredIntent(
                        ref_id=ServerPlanRefId(plan._next_ref()),
                        model_cls=model_cls,
                        source=cast("ObjectServerRef[DatabaseObjectRow[SysId]]", instance),
                        config=intent_versioning_extended._VersionedUpdateDeferredIntentConfig(
                            staging_ctx=sc,
                            source_value=cast("DatabaseObjectRow[SysId] | None", literal_instance),
                            after_refs=frozenset(after_refs),
                        ),
                    ),
                    variant="object",
                ),
            ),
        )

    @pure_lazy
    def _combine_physical_update_effects[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        mutation_refs: Sequence[ServerPlanRefId],
    ) -> ObjectServerRef[T | None]:
        from impl.common.l2070_server_plan.steps.collect_results import MaterializedFlattenResultsAfterDepsStep

        plan = self._get_transaction_plan_lazy()
        source_refs = [str(intent_versioning_extended.versioned_update_write_effect_ref(mutation_ref)) for mutation_ref in mutation_refs]
        completion: ObjectServerRef[T | None] = self._add_intent_ref(
            MaterializedFlattenResultsAfterDepsStep(
                ServerPlanRefId(plan._next_ref()),
                None,
                source_refs,
            ),
            variant="object",
        )
        _record_versioned_write_tail_ref(self, completion)
        return completion

    @staticmethod
    @pure_lazy
    def _has_multitable_physical_owners(model_cls: type[DatabaseObjectRow]) -> bool:
        from impl.common.l2060_query_spec.polymorphic_multitable_cte import get_multitable_polymorphic_source_models

        return len(get_multitable_polymorphic_source_models(model_cls)) > 1

    @pure_lazy
    def _update_physical_owners_by_id_lazy[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        object_id: SysId,
        updates: Mapping[str, Any],
        *,
        after_refs: Sequence[ServerPlanRefId],
    ) -> PhysicalOwnerMutationPlan[T]:
        from impl.common.l2060_query_spec.polymorphic_multitable_cte import (
            get_multitable_polymorphic_source_models,
        )

        physical_models = get_multitable_polymorphic_source_models(model_cls)
        if len(physical_models) <= 1:
            raise ValueError("Physical-owner mutation planning requires multiple owners")
        plan = self._get_transaction_plan_lazy()
        context_refs = get_versioned_lazy_context_refs(self)
        mutation_refs: list[ServerPlanRefId] = []
        execution_dependency_refs: list[ServerPlanRefId] = []
        terminal_dependency_ref: ServerPlanRefId | None = None
        for owner_model in physical_models:
            self._mark_commit_branch_touched_model_lazy(owner_model, operation="update")
            owner_ctx = self._get_versioned_staging_context(owner_model, context_refs=context_refs)
            mutation = self._add_intent(
                intent_versioning_extended.VersionedUpdateByIdIntent[T](
                    ref_id=ServerPlanRefId(plan._next_ref()),
                    model_cls=owner_model,
                    config=intent_versioning_extended._shape_versioned_update_by_id_intent_config(
                        owner_model,
                        object_id,
                        updates,
                        owner_ctx,
                        after_refs=frozenset(after_refs) | _current_versioned_write_tail_refs(self, plan=plan),
                        dependency_only=intent_versioning_extended.VersionedDependencyOnlyFlag(True),
                        physical_owner_only=True,
                    ),
                ),
            )
            _record_versioned_write_tail(
                self,
                mutation,
                context="physical owner point update",
            )
            mutation_shape = inspect_server_value_shape_for_planning(
                mutation,
                site="physical owner point update",
            )
            if mutation_shape.symbolic_ref_id is None:
                raise TypeError("Physical-owner mutation must publish a plan ref")
            mutation_ref = mutation_shape.symbolic_ref_id
            mutation_refs.append(mutation_ref)
            terminal_dependency_ref = intent_versioning_extended.versioned_update_write_effect_ref(mutation_ref)
            execution_dependency_refs.append(terminal_dependency_ref)
        if terminal_dependency_ref is None:
            raise TypeError("Physical-owner mutation must publish a terminal dependency ref")
        return PhysicalOwnerMutationPlan(
            mutation_refs=tuple(mutation_refs),
            execution_dependency_refs=tuple(execution_dependency_refs),
            terminal_dependency_ref=terminal_dependency_ref,
        )

    @pure_lazy
    def update_by_id_lazy[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        object_id: SysId,
        updates: Mapping[str, Any] | None = None,
        *,
        after_refs: Sequence[ServerPlanRefId] = (),
    ) -> LazyResult[T | None]:
        """Versioned update-by-id: select row, apply updates, re-stage.

        For versioned models, routes through ``VersionedUpdateByIdIntent``
        which lowers to a versioned select + staged INSERT.
        """
        updates_dict = dict(updates) if updates else {}
        if not updates_dict:
            raise ValueError("update_by_id requires at least one update")

        protected_fields = frozenset({"sys_id", "revision_id", "staged_commit_id", "deleted"})
        bad = protected_fields & updates_dict.keys()
        if bad:
            raise ValueError(f"Cannot update protected fields: {', '.join(sorted(bad))}")

        if not self._check_versioned_or_delegate(model_cls):
            plan = self._get_transaction_plan_lazy()
            _check_write_permission_lazy(self, model_cls)
            updates_payload = intent_crud._shape_update_fields_payload(updates_dict)
            ordered_after_refs = frozenset(after_refs) | frozenset(
                ServerPlanRefId(prior_step.ref_id) for prior_step in plan._steps if "write" in prior_step.step_tags()
            )
            return self._add_intent(
                intent_crud.UpdateByIdIntent(
                    ref_id=ServerPlanRefId(plan._next_ref()),
                    model_cls=model_cls,
                    config=intent_crud._UpdateByIdIntentConfig(
                        sys_id=object_id,
                        updates=updates_payload,
                        apply_update_rules=intent_crud._update_hook_transformer_from_hook_context(
                            model_cls,
                            hook_registry=getattr(plan, "_auto_api_hook_registry", None),
                            session_id=getattr(self, "session_id", None),
                        ),
                        after_refs=ordered_after_refs,
                    ),
                ),
            )

        has_physical_owner_mutations = self._has_multitable_physical_owners(model_cls)
        if has_physical_owner_mutations:
            mutation_plan = self._update_physical_owners_by_id_lazy(
                model_cls,
                object_id,
                updates_dict,
                after_refs=after_refs,
            )
            result = (
                self.query_lazy(model_cls)
                .filter(
                    field(model_cls.sys_id) == object_id,
                )
                .first_after_refs_lazy(after_refs=mutation_plan.execution_dependency_refs)
            )
            return _record_versioned_write_tail(
                self,
                result,
                context="update_by_id_lazy physical owner update",
            )

        permission_context_ref, permission_context_type = _versioned_permission_context(
            self,
            model_cls,
        )
        self._mark_commit_branch_touched_model_lazy(cast("type[DatabaseObjectRow[SysId]]", model_cls), operation="update")
        context_refs = get_versioned_lazy_context_refs(self)
        sc = self._get_versioned_staging_context(model_cls, context_refs=context_refs)
        plan = self._get_transaction_plan_lazy()
        return _record_versioned_write_tail(
            self,
            self._add_intent(
                intent_versioning_extended.VersionedUpdateByIdIntent(
                    ref_id=ServerPlanRefId(plan._next_ref()),
                    model_cls=model_cls,
                    config=intent_versioning_extended._shape_versioned_update_by_id_intent_config(
                        model_cls,
                        object_id,
                        updates_dict,
                        sc,
                        after_refs=frozenset(after_refs) | _current_versioned_write_tail_refs(self, plan=plan),
                        permission_context_ref=permission_context_ref,
                        permission_context_type=permission_context_type,
                    ),
                ),
            ),
            context="update_by_id_lazy versioned update",
        )

    @pure_lazy
    def update_by_id_dependency_ref[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        object_id: SysId,
        updates: Mapping[str, Any] | None = None,
        *,
        after_refs: Sequence[ServerPlanRefId] = (),
    ) -> ObjectServerRef[T | None]:
        """Add a versioned update-by-id and return only its dependency ref."""
        updates_dict = dict(updates) if updates else {}
        if not updates_dict:
            raise ValueError("update_by_id requires at least one update")
        protected_fields = frozenset({"sys_id", "revision_id", "staged_commit_id", "deleted"})
        bad = protected_fields & updates_dict.keys()
        if bad:
            raise ValueError(f"Cannot update protected fields: {', '.join(sorted(bad))}")
        if not self._check_versioned_or_delegate(model_cls):
            base_write_txn = cast(_VersionedWriteTxnState, self).base_write_transaction
            _require_same_lazy_plan_owner(
                self,
                base_write_txn,
                context="update_by_id_dependency_ref delegate",
            )
            return WriteTransactionLazyMixin.update_by_id_dependency_ref(
                cast(Any, base_write_txn),
                model_cls,
                object_id,
                updates_dict,
            )
        has_physical_owner_mutations = self._has_multitable_physical_owners(model_cls)
        if has_physical_owner_mutations:
            mutation_plan = self._update_physical_owners_by_id_lazy(
                model_cls,
                object_id,
                updates_dict,
                after_refs=after_refs,
            )
            return ServerRefs.from_ref_id(
                mutation_plan.terminal_dependency_ref,
                variant="object",
                type_hint=model_cls,
            )
        self._mark_commit_branch_touched_model_lazy(cast("type[DatabaseObjectRow[SysId]]", model_cls), operation="update")
        context_refs = get_versioned_lazy_context_refs(self)
        sc = self._get_versioned_staging_context(model_cls, context_refs=context_refs)
        plan = self._get_transaction_plan_lazy()
        return cast(
            "ObjectServerRef[T | None]",
            _record_versioned_write_tail_ref(
                self,
                self._add_intent_ref(
                    intent_versioning_extended.VersionedUpdateByIdIntent(
                        ref_id=ServerPlanRefId(plan._next_ref()),
                        model_cls=model_cls,
                        config=intent_versioning_extended._shape_versioned_update_by_id_intent_config(
                            model_cls,
                            object_id,
                            updates_dict,
                            sc,
                            after_refs=frozenset(after_refs) | _current_versioned_write_tail_refs(self, plan=plan),
                            dependency_only=intent_versioning_extended.VersionedDependencyOnlyFlag(True),
                        ),
                    ),
                    variant="object",
                ),
            ),
        )

    @pure_lazy
    def update_by_runtime_id_dependency_ref[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        object_id_slot: SqlRuntimeBindSlot,
        updates: Mapping[str, Any],
        *,
        after_refs: Sequence[ServerPlanRefId] = (),
    ) -> ObjectServerRef[T | None]:
        """Add a dependency-only versioned update for a request-owned id slot."""
        if not self._check_versioned_or_delegate(model_cls):
            msg = "Runtime-slot dependency updates require a versioned model"
            raise TypeError(msg)
        updates_dict = dict(updates)
        if not updates_dict:
            raise ValueError("update_by_runtime_id requires at least one update")
        from impl.common.l2060_query_spec.polymorphic_multitable_cte import (
            get_multitable_polymorphic_source_models,
        )

        physical_models = get_multitable_polymorphic_source_models(model_cls)
        context_refs = get_versioned_lazy_context_refs(self)
        plan = self._get_transaction_plan_lazy()
        mutation_refs: list[ServerPlanRefId] = []
        direct_mutation_ref: ServerPlanRefId | None = None
        for owner_model in physical_models or (model_cls,):
            self._mark_commit_branch_touched_model_lazy(owner_model, operation="update")
            staging_ctx = self._get_versioned_staging_context(owner_model, context_refs=context_refs)
            update_ref = self._add_intent_ref(
                intent_versioning_extended.VersionedUpdateByIdDeferredIntent(
                    ref_id=ServerPlanRefId(plan._next_ref()),
                    model_cls=owner_model,
                    sys_id=ServerRefs.scalar(object_id_slot),
                    config=intent_versioning_extended._VersionedUpdateByIdDeferredIntentConfig(
                        updates=intent_versioning_extended._shape_versioned_update_fields_payload(updates_dict),
                        staging_ctx=staging_ctx,
                        after_refs=frozenset(after_refs) | _current_versioned_write_tail_refs(self, plan=plan),
                        dependency_only=intent_versioning_extended.VersionedDependencyOnlyFlag(True),
                        physical_owner_only=bool(physical_models),
                    ),
                ),
                variant="object",
            )
            _record_versioned_write_tail_ref(self, update_ref)
            update_shape = inspect_server_value_shape_for_planning(
                update_ref,
                site="update_by_runtime_id_dependency_ref",
            )
            assert update_shape.symbolic_ref_id is not None
            if physical_models:
                mutation_refs.append(update_shape.symbolic_ref_id)
            else:
                direct_mutation_ref = update_shape.symbolic_ref_id
        if physical_models:
            return self._combine_physical_update_effects(model_cls, mutation_refs)
        if direct_mutation_ref is None:
            raise TypeError("Direct versioned update must publish one mutation ref")
        return ServerRefs.from_ref_id(
            intent_versioning_extended.versioned_update_write_effect_ref(direct_mutation_ref),
            variant="object",
            type_hint=model_cls,
        )

    # ── Delete ──

    @pure_lazy
    def delete_by_id_lazy[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        object_id: object,
    ) -> LazyResult[bool]:
        """Delete one row through the generic intent path.

        Dispatch symbolic vs. literal id at the Python input boundary (#2372 §3.1):

        * ``ScalarServerRef[SysId]`` or step-backed ``LazyResult`` -> symbolic
          ``DeleteDeferredIntent`` that reads the id from the prior step's CTE.
        * raw ``SysId`` or literal-backed ``LazyResult`` -> concrete
          ``DeleteIntent`` with the raw id.
        """
        if not self._check_versioned_or_delegate(model_cls):
            return super().delete_by_id_lazy(model_cls, object_id)
        self._mark_commit_branch_delete_side_effect_tables_lazy(cast("type[DatabaseObjectRow[SysId]]", model_cls))
        plan = self._get_transaction_plan_lazy()
        from impl.common.l2060_query_spec.polymorphic_multitable_cte import get_multitable_polymorphic_source_models

        physical_models = get_multitable_polymorphic_source_models(model_cls)
        if len(physical_models) > 1:
            context_refs = get_versioned_lazy_context_refs(self)
            sc = self._get_versioned_staging_context(model_cls, context_refs=context_refs)
            owners = tuple(
                intent_versioning_extended.VersionedDeletePhysicalOwner(
                    owner_model,
                    self._get_versioned_staging_context(owner_model, context_refs=context_refs),
                )
                for owner_model in physical_models
            )
            for owner in owners:
                self._mark_commit_branch_delete_side_effect_tables_lazy(owner.model_cls)
            pending_refs: frozenset[ServerPlanRefId] = getattr(self, "_pending_delete_after_refs", frozenset())
            object.__setattr__(self, "_pending_delete_after_refs", frozenset())
            source_id = _row_id_to_sys_id(object_id) if isinstance(object_id, RowId) else object_id
            return _record_versioned_write_tail(
                self,
                self._add_intent(
                    intent_versioning_extended.VersionedDeletePhysicalOwnersIntent(
                        ServerPlanRefId(plan._next_ref()),
                        sys_id=ServerRefs.scalar(source_id),
                        model_cls=model_cls,
                        config=ServerRefs.scalar(
                            intent_versioning_extended._VersionedDeletePhysicalOwnersConfig(
                                staging_ctx=sc,
                                owners=owners,
                                after_refs=_current_versioned_write_tail_refs(self, plan=plan) | pending_refs,
                            ),
                        ),
                    )
                ),
                context="delete_by_id_lazy physical owner delete",
            )
        if isinstance(object_id, ScalarServerRef):
            return self._add_intent(
                intent_crud.DeleteDeferredIntent(
                    ref_id=ServerPlanRefId(plan._next_ref()),
                    model_cls=model_cls,
                    sys_id=cast("ScalarServerRef[SysId]", object_id),
                    config=intent_crud._DeleteIntentConfig(),
                ),
            )
        source_ref = (
            _published_lazy_ref_id(object_id, context="delete_by_id_lazy object_id") if isinstance(object_id, LazyResult) else None
        )
        if source_ref is not None:
            return self._add_intent(
                intent_crud.DeleteDeferredIntent(
                    ref_id=ServerPlanRefId(plan._next_ref()),
                    model_cls=model_cls,
                    sys_id=cast(
