    @pure_lazy
    def _insert_many_raw_lazy[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        columns: Sequence[str],
        rows: object,
        *,
        db_column_source: type[Any] | None,
        emit_side_effects: bool,
        after_refs: Sequence[ServerPlanRefId] = (),
    ) -> LazyResult[int]:
        """Stage raw rows with an explicit side-effect publication policy."""
        if not self._check_versioned_or_delegate(model_cls):
            return super().insert_many_raw_lazy(model_cls, columns, rows, db_column_source)
        _check_write_permission_lazy(self, model_cls)
        permission_context_ref, permission_context_type = _versioned_permission_context(
            self,
            model_cls,
        )
        if isinstance(rows, Sequence) and len(rows) == 0:
            return LazyResult.of(0)
        normalized_columns = tuple(columns)
        normalized_rows = rows
        if isinstance(rows, Sequence) and not isinstance(rows, str | bytes):
            raw_field_names = _normalize_raw_field_names(model_cls, normalized_columns, db_column_source)
            normalized_columns, normalized_rows = _raw_rows_with_model_defaults(
                model_cls,
                raw_field_names,
                cast("Sequence[Sequence[object]]", rows),
            )
            db_column_source = None
            if "sys_id" not in normalized_columns:
                normalized_columns = ("sys_id", *normalized_columns)
                normalized_rows = tuple((SysId.new(), *tuple(row)) for row in normalized_rows)
        self._mark_commit_branch_touched_model_lazy(cast("type[DatabaseObjectRow[SysId]]", model_cls), operation="insert")
        context_refs = get_versioned_lazy_context_refs(self)
        sc = self._get_versioned_staging_context(model_cls, context_refs=context_refs)
        plan = self._get_transaction_plan_lazy()
        prior_refs = _current_versioned_write_tail_refs(self, plan=plan) | frozenset(after_refs)
        isolate_from_sql_batch = bool(prior_refs)
        if isinstance(normalized_rows, intent_versioning_extended.DeferredRawRowSource):
            # A deferred source is already a SQL-visible relation. Explicit
            # dependencies order it after prior writes without forcing a
            # second executor batch or database round trip.
            isolate_from_sql_batch = False
        elif isinstance(normalized_rows, Sequence) and not isinstance(normalized_rows, str | bytes):
            raw_field_names = _normalize_raw_field_names(model_cls, normalized_columns, db_column_source)
            if "sys_id" in raw_field_names:
                sys_id_index = tuple(raw_field_names).index("sys_id")
                raw_sys_ids = {str(row[sys_id_index]) for row in cast("Sequence[Sequence[object]]", normalized_rows)}
                deleted_by_model = getattr(self, "_versioned_literal_delete_ids_by_model", {})
                assert isinstance(deleted_by_model, dict)
                isolate_from_sql_batch = bool(after_refs) or bool(
                    prior_refs
                    and raw_sys_ids
                    & deleted_by_model.get(
                        cast("type[DatabaseObjectRow[SysId]]", model_cls),
                        set(),
                    )
                )
        return _record_versioned_write_tail(
            self,
            self._add_intent(
                intent_versioning_extended.VersionedRawInsertManyIntent(
                    ref_id=ServerPlanRefId(plan._next_ref()),
                    model_cls=model_cls,
                    config=ServerRefs.scalar(
                        intent_versioning_extended._VersionedRawInsertManyConfig(
                            staging_ctx=sc,
                            columns=normalized_columns,
                            rows=normalized_rows,
                            db_column_source=_optional_database_object_model(db_column_source),
                            after_refs=prior_refs,
                            permission_context_ref=permission_context_ref,
                            permission_context_type=permission_context_type,
                            isolate_from_sql_batch=isolate_from_sql_batch,
                            emit_side_effects=emit_side_effects,
                        ),
                    ),
                ),
            ),
            context="insert_many_raw_lazy versioned raw insert",
        )

