    @pure_lazy
    def create_branch_lazy(
        self: VersionedWriteTransactionLazyMixin,
        name: str,
        *,
        from_revision_id: RevisionId | None = None,
        workspace_id: WorkspaceId | None = None,
        tip_materialization: BranchTipMaterialization = BranchTipMaterialization.MATERIALIZED,
        branchpoint_materialization: BranchPointMaterialization = BranchPointMaterialization.INHERITED,
    ) -> LazyResult[BranchId]:
        """Create a new branch through the versioned branch intent path."""
        from l7000_versioned_schema.branch_materialization import (
            resolve_branch_tip_materialization_for_tests,
            resolve_branchpoint_materialization_for_tests,
        )

        txn = cast(_VersionedWriteTxnState, self)
        branch_name = BranchName(name)
        plan = self._get_transaction_plan_lazy()
        builder = LazyBuilderContext(plan)
        resolved_tip_materialization = resolve_branch_tip_materialization_for_tests(tip_materialization)
        resolved_branchpoint_materialization = resolve_branchpoint_materialization_for_tests(branchpoint_materialization)
        branch_name_ref = cast("ScalarServerRef[BranchName]", builder.ref_for(branch_name))
        permission_context = bound_permission_context_transport_lazy(txn)
        tip_materialization_ref = cast(
            "ScalarServerRef[BranchTipMaterialization]",
            builder.ref_for(resolved_tip_materialization),
        )
        branchpoint_materialization_ref = cast(
            "ScalarServerRef[BranchPointMaterialization]",
            builder.ref_for(resolved_branchpoint_materialization),
        )
        current_branch_row_ref_id: ServerPlanRefId | None = None
        if from_revision_id is None:
            if workspace_id is None:
                return self._add_intent(
                    intent_versioning.CreateBranchFromCurrentContextIntent(
                        ref_id=ServerPlanRefId(plan._next_ref()),
                        domain=txn.domain,
                        branch_name=branch_name_ref,
                        tip_materialization=tip_materialization_ref,
                        branchpoint_materialization=branchpoint_materialization_ref,
                        permission_context=permission_context,
                    ),
                )
            return self._add_intent(
                intent_versioning.CreateBranchFromCurrentTipIntent(
                    ref_id=ServerPlanRefId(plan._next_ref()),
                    domain=txn.domain,
                    branch_name=branch_name_ref,
                    workspace_id=cast(
                        "ScalarServerRef[WorkspaceId]",
                        builder.ref_for(workspace_id),
                    ),
                    tip_materialization=tip_materialization_ref,
                    branchpoint_materialization=branchpoint_materialization_ref,
                    permission_context=permission_context,
                ),
            )

        context_refs = get_versioned_lazy_context_refs(self)
        if workspace_id is not None:
            workspace_ref = cast(
                "ScalarServerRef[WorkspaceId]",
                builder.ref_for(workspace_id),
            )
        elif context_refs.workspace is not UNSET:
            workspace_ref = cast(
                "ScalarServerRef[WorkspaceId]",
                normalize_scalar_input(
                    context_refs.workspace,
                    context=DiagnosticLabel("create_branch_lazy current workspace context"),
                ),
            )
        else:
            resolved_workspace_id = txn.domain.workspace_id or WorkspaceId.default()
            workspace_ref = cast(
                "ScalarServerRef[WorkspaceId]",
                builder.ref_for(resolved_workspace_id),
            )

        symbolic_revision = False
        resolved_revision_id = from_revision_id
        if resolved_revision_id is None and current_branch_row_ref_id is not None:
            symbolic_revision = True
        context_revision_ref = versioned_lazy_context_revision_ref(
            context_refs,
            context=DiagnosticLabel("create_branch_lazy current revision context"),
        )
        if resolved_revision_id is None and not symbolic_revision:
            resolved_revision_id = txn.base_revision_id
        from_revision_ref = (
            ServerRefs.from_ref_id(
                f"{current_branch_row_ref_id}.tip_revision_sys_id",
                variant="scalar",
                type_hint=RevisionId,
            )
            if symbolic_revision and current_branch_row_ref_id is not None
            else context_revision_ref
            if resolved_revision_id is None and context_revision_ref is not None
            else cast(
                "ScalarServerRef[RevisionId]",
                builder.ref_for(resolved_revision_id),
            )
        )
        if resolved_revision_id is None and not symbolic_revision:
            return self._add_intent(
                intent_versioning.CreateEmptyBranchIntent(
                    ref_id=ServerPlanRefId(plan._next_ref()),
                    domain=txn.domain,
                    branch_name=branch_name_ref,
                    workspace_id=workspace_ref,
                    tip_materialization=tip_materialization_ref,
                    from_revision_id=from_revision_ref,
                    permission_context=bound_permission_context_transport_lazy(txn),
                ),
            )
        return self._add_intent(
            intent_versioning.CreateSeededBranchIntent(
                ref_id=ServerPlanRefId(plan._next_ref()),
                domain=txn.domain,
                branch_name=branch_name_ref,
                workspace_id=workspace_ref,
                from_revision_id=from_revision_ref,
                tip_materialization=tip_materialization_ref,
                branchpoint_materialization=branchpoint_materialization_ref,
                permission_context=bound_permission_context_transport_lazy(txn),
            ),
        )

    @pure_lazy
    def delete_returning_lazy[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        object_id: SysId,
        returning_columns: Sequence[str] | None = None,
    ) -> LazyResult[dict[str, Any] | None]:
        """Delete one row and return the requested payload via generic intent lowering."""
        if not self._check_versioned_or_delegate(model_cls):
            _check_write_permission_lazy(self, model_cls)
            plan = self._get_transaction_plan_lazy()
            returning_payload = intent_crud._shape_returning_columns_payload(
                None if returning_columns is None else list(returning_columns),
            )
            ref = plan.add_step(
                intent_crud.DeleteReturningIntent(
                    ref_id=ServerPlanRefId(plan._next_ref()),
                    model_cls=model_cls,
                    sys_id=ServerRefs.scalar(object_id),
                    config=ServerRefs.scalar(
                        intent_crud._DeleteReturningPayload(returning_columns=returning_payload),
                    ),
                ),
            )
            assert ref.ref_id is not None
            return cast(
                "LazyResult[dict[str, Any] | None]",
                self._publish_pending_lazy_ref(ref.ref_id, expected_type=None),
            )

        self._mark_commit_branch_touched_model_lazy(
            cast("type[DatabaseObjectRow[SysId]]", model_cls),
            operation="delete",
        )
        plan = self._get_lazy_plan()
        sys_id_ref = ServerRefs.scalar(object_id)
        returning_payload = intent_crud._shape_returning_columns_payload(
            None if returning_columns is None else list(returning_columns),
        )
        ref = plan.add_step(
            intent_crud.DeleteReturningIntent(
                ref_id=ServerPlanRefId(plan._next_ref()),
                model_cls=model_cls,
                sys_id=sys_id_ref,
                config=ServerRefs.scalar(
                    intent_crud._DeleteReturningPayload(returning_columns=returning_payload),
                ),
            ),
        )
        assert ref.ref_id is not None
        return cast(
            "LazyResult[dict[str, Any] | None]",
            self._publish_pending_lazy_ref(ref.ref_id, expected_type=None),
        )


def _coerce_revision_id(value: object) -> RevisionId:
    return value if isinstance(value, RevisionId) else RevisionId(str(value))


@pure_lazy
def _literal_revision_source_ref(value: object) -> ScalarServerRef[RevisionId] | None:
    if isinstance(value, ScalarServerRef):
        return None
    if isinstance(value, RevisionId):
        if value.is_current():
            return None
        return ServerRefs.scalar(value)
    unwrap_to_str = getattr(value, "unwrap_to_str", None)
    if callable(unwrap_to_str) and type(value).__name__ == "RevisionId":
        revision_id = RevisionId(cast("Callable[[], str]", unwrap_to_str)())
        if revision_id.is_current():
            return None
        return ServerRefs.scalar(revision_id)
    if isinstance(value, str):
        revision_id = RevisionId(value)
        if revision_id.is_current():
            return None
        return ServerRefs.scalar(revision_id)
    if value is not None:
        raw_value = str(value)
        if "seed_" not in raw_value:
            revision_id = RevisionId(raw_value)
            if revision_id.is_current():
                return None
            return ServerRefs.scalar(revision_id)
    return None


@pure_lazy
def _versioned_permission_context(
    txn: VersionedReadTransactionLazyMixin | VersionedWriteTransactionLazyMixin,
    model_cls: type[DatabaseObjectRow],
) -> tuple[ServerPlanRefId | None, type[ResolvedSessionContext] | None]:
    from l2050_transaction.lazy_mixin import bound_permission_context_transport_lazy
    from l4000_permissions.lazy_permission_support import permission_planning_input_for_model

    permission_input = permission_planning_input_for_model(txn, model_cls)
    if permission_input.context_ref is None:
        return None, None
    transport = bound_permission_context_transport_lazy(txn)
    return transport.ref_id, transport.value_type


@pure_lazy
def _attach_versioned_query_permissions(
    txn: VersionedReadTransactionLazyMixin | VersionedWriteTransactionLazyMixin,
    builder: ReadQueryBuilder[Any] | WriteQueryBuilder[Any],
    model_cls: type[DatabaseObjectRow],
) -> None:
    """Bind versioned query permissions to the transaction's exact context product."""
    context_ref_id, context_type = _versioned_permission_context(txn, model_cls)
    if context_ref_id is None or context_type is None:
        return
    builder._with_permission_context(context_ref_id, context_type)


class _VersionedReadQueryBuilder[T: VersionedObjectRow[SysId]](ReadQueryBuilder[T]):
    """Read query builder that emits explicit-revision versioned read intents."""

    __slots__ = ("_txn",)

    def __init__(self, txn: VersionedReadTransactionLazyMixin, model_cls: type[T]) -> None:
        super().__init__(txn._get_transaction_plan_lazy(), model_cls)
        self._txn = txn
        _attach_versioned_query_permissions(txn, self, model_cls)

    def include_deleted(self: Self) -> Self:
        """Include tombstones in the versioned logical snapshot."""
        self._include_deleted = True
        return self

    def insert_into[U: DatabaseObjectRow](
        self: _VersionedReadQueryBuilder[T],
        target_cls: type[U],
    ) -> Any:
        """Insert a typed versioned source relation into a target model."""
        from l2060_query_builder.plan_query_builder import PlanInsertFromQueryBuilder

        return PlanInsertFromQueryBuilder(self, target_cls)

    def _build_unversioned_insert_from_versioned_query_returning_step(self, config: object) -> Any:
        from impl.common.l2070_server_plan.steps.insert_from_query import (
            _InsertFromQueryConfig,
            _InsertFromVersionedQueryReturningIntent,
            prepare_insert_from_versioned_query_returning,
        )

        assert isinstance(config, _InsertFromQueryConfig)
        plan = self._txn._get_transaction_plan_lazy()
        return _InsertFromVersionedQueryReturningIntent(
            ServerPlanRefId(plan._next_ref()),
            config=prepare_insert_from_versioned_query_returning(config),
            revision_id=self._txn._current_revision_source_ref(
                context="versioned insert-from-query revision context",
            ),
            domain=_txn_domain(self._txn),
        )

    @pure_lazy
    def lazy(
        self: _VersionedReadQueryBuilder[T],
        *,
        _internal_projection: bool = False,
    ) -> LazyResult[Sequence[T]]:
        spec = self._build_spec()
        from l2060_query_builder.search_mode import classify_query_search_mode, invalid_hybrid_message

        search_mode = classify_query_search_mode(spec)
        if search_mode == "invalid_hybrid":
            raise ValueError(invalid_hybrid_message())
        if search_mode in {"fts_only", "vector_only", "hybrid"} or isinstance(spec.source, ValuesSource):
            plan = self._txn._get_transaction_plan_lazy()
            step = intent_query.QueryExecuteIntent(
                ref_id=ServerPlanRefId(plan._next_ref()),
                model_cls=self._model_cls,
                config=intent_query._QueryExecuteConfig(
                    query_spec=spec,
                    raw_mode=_internal_projection,
                    after_refs=(
                        _current_versioned_write_tail_refs(self._txn, plan=plan)
                        | frozenset(ServerPlanRefId(step.ref_id) for step in plan._steps)
                    ),
                ),
            )
            return self._with_includes_lazy(self._publish_query_step_lazy(step))
        plan = self._txn._get_transaction_plan_lazy()
        flush_pending = getattr(self._txn, "_flush_pending_lazy_ops_to_plan", None)
        flushed_refs: frozenset[ServerPlanRefId] = frozenset()
        if callable(flush_pending):
            raw_flushed_refs = flush_pending()
            if not isinstance(raw_flushed_refs, list | tuple | set | frozenset):
                raise TypeError("Pending lazy operation refs must be a finite collection")
            flushed_refs = frozenset(ServerPlanRefId(str(ref)) for ref in raw_flushed_refs)
        after_refs = (
            flushed_refs
            | _current_versioned_write_tail_refs(self._txn, plan=plan)
            | frozenset(ServerPlanRefId(step.ref_id) for step in plan._steps)
        )
        versioned_config = ServerRefs.scalar(
            intent_versioning_extended._VersionedQueryConfig(
                query_spec=spec,
                revision_id=self._txn._current_revision_source_ref(
                    context="versioned query revision context",
                ),
                domain=_txn_domain(self._txn),
                raw_mode=_internal_projection,
                after_refs=after_refs,
            ),
        )
        if _internal_projection:
            raw_step = intent_versioning_extended.VersionedQueryRawIntent(
                ref_id=ServerPlanRefId(plan._next_ref()),
                model_cls=self._model_cls,
                config=versioned_config,
            )
            projected_step = cast("ServerPlanStep[Sequence[T]]", raw_step)
            return self._with_includes_lazy(self._publish_query_step_lazy(projected_step))
        versioned_step: intent_versioning_extended.VersionedQueryIntent[T] = intent_versioning_extended.VersionedQueryIntent(
            ref_id=ServerPlanRefId(plan._next_ref()),
            model_cls=self._model_cls,
            config=versioned_config,
        )
        return self._with_includes_lazy(self._publish_query_step_lazy(versioned_step))

    @pure_lazy
    def _projection_rows_lazy(self: _VersionedReadQueryBuilder[T]) -> LazyResult[Sequence[Any]]:
        """Return tuple-projection inputs as an exact SQL-visible raw relation."""
        from impl.common.l2070_server_plan.steps.versioned_lazy_support import (
            RawDictProjectionRowsStep,
        )
        from impl.common.l2070_server_plan.steps.versioned_query_steps import (
            _selected_projection_output_aliases,
            _simple_select_projection_type_hints,
        )

        query_spec = self._build_spec()
        projection_columns = _selected_projection_output_aliases(query_spec, self._model_cls)
        if not projection_columns:
            msg = "Versioned tuple projection requires explicit output columns"
            raise ValueError(msg)
        column_type_hints = _simple_select_projection_type_hints(self._model_cls, query_spec)
        if column_type_hints is None:
            msg = "Versioned tuple projection requires complete SQL column type hints"
            raise TypeError(msg)
        from impl.common.l2070_server_plan.steps.large_column_read import (
            inline_large_column_alias_columns,
            inline_large_column_sql_column_type_hints,
        )
        from l1000_schema.large_column import get_large_column_configs, large_column_pointer_name
        from l2070_batching.sql_column_type_hints import combine_sql_column_type_hints

        projected = set(projection_columns)
        selected_large_columns = tuple(config for config in get_large_column_configs(self._model_cls) if str(config.column) in projected)
        if selected_large_columns:
            projection_columns = tuple(
                dict.fromkeys(
                    (
                        *projection_columns,
                        *(large_column_pointer_name(config.column) for config in selected_large_columns),
                        *inline_large_column_alias_columns(self._model_cls),
                    ),
                ),
            )
            column_type_hints = combine_sql_column_type_hints(
                projection_columns,
                column_type_hints,
                inline_large_column_sql_column_type_hints(self._model_cls),
            )
        from impl.common.l2070_server_plan.steps.versioned_query_steps import (
            _joined_projection_support_type_hints,
        )
        from l2070_batching.publication import hinted_columns

        missing_hint_columns = tuple(column for column in projection_columns if column not in hinted_columns(column_type_hints))
        if missing_hint_columns:
            support_hints = _joined_projection_support_type_hints(
                self._model_cls,
                query_spec,
                missing_hint_columns,
            )
            if support_hints is not None:
                column_type_hints = combine_sql_column_type_hints(
                    projection_columns,
                    column_type_hints,
                    support_hints,
                )
        column_type_hints = column_type_hints.filtered(set(projection_columns)).require_complete(projection_columns)
        source = self.lazy(_internal_projection=True)
        if query_spec.search_op is not None:
            return cast("LazyResult[Sequence[Any]]", source)
        source_ref = object.__getattribute__(source, "_step_ref_id")
        if source_ref is None:
            msg = "Versioned query source must publish a relation reference for raw projection rows"
            raise RuntimeError(msg)
        raw_step = RawDictProjectionRowsStep(
            ServerPlanRefId(self._plan._next_ref()),
            source_ref=ServerPlanRefId(source_ref),
            columns=projection_columns,
            column_type_hints=column_type_hints,
            query_spec=query_spec,
            model_cls=self._model_cls,
        )
        return cast("LazyResult[Sequence[Any]]", self._publish_query_step_lazy(raw_step))

    @overload
    def execute_lazy(
        self: _VersionedReadQueryBuilder[T],
        *,
        _internal_projection: Literal[False] = False,
    ) -> LazyResult[Sequence[T]]: ...

    @overload
    def execute_lazy(
        self: _VersionedReadQueryBuilder[T],
        *,
        _internal_projection: Literal[True],
    ) -> LazyResult[list[dict[str, Any]]]: ...

    @pure_lazy
    def execute_lazy(
        self: _VersionedReadQueryBuilder[T],
        *,
        _internal_projection: bool = False,
    ) -> LazyResult[Sequence[T]] | LazyResult[list[dict[str, Any]]]:
        result = self.lazy(_internal_projection=_internal_projection)
        if _internal_projection:
            return cast("LazyResult[list[dict[str, Any]]]", result)
        return result

    @pure_lazy
    def _versioned_single_row_lazy(
        self: _VersionedReadQueryBuilder[T],
        *,
        strict_one: bool,
        after: Sequence[LazyResult[Any]] = (),
    ) -> LazyResult[T | None]:
        """Publish a single-row read at the transaction's explicit revision.

        Single-row terminals cannot fall back to ``ReadQueryBuilder``: those
        intents only route through versioned storage when the lowering context
        itself is versioned, which is not the case for versioned read
        transactions. They would otherwise read the (empty) physical base table.
        """
        spec = self._build_spec()
        if getattr(spec, "limit", None) is None:
            spec = replace(spec, limit=2 if strict_one else 1)
        plan = self._txn._get_transaction_plan_lazy()
        flush_pending = getattr(self._txn, "_flush_pending_lazy_ops_to_plan", None)
        raw_flushed_refs = flush_pending() if callable(flush_pending) else ()
        if not isinstance(raw_flushed_refs, list | tuple | set | frozenset):
            raise TypeError("Pending lazy operation refs must be a finite collection")
        flushed_refs = frozenset(ServerPlanRefId(str(ref)) for ref in raw_flushed_refs)
        after_refs = (
            flushed_refs
            | _current_versioned_write_tail_refs(self._txn, plan=plan)
            | frozenset(ServerPlanRefId(str(step.ref_id)) for step in plan._steps)
        )
        step = intent_versioning_extended.VersionedQueryFirstIntent(
            ref_id=ServerPlanRefId(plan._next_ref()),
            model_cls=self._model_cls,
            config=ServerRefs.scalar(
                intent_versioning_extended._VersionedQueryFirstConfig(
                    query_spec=spec,
                    revision_id=self._txn._current_revision_source_ref(
                        context="versioned single-row query revision context",
                    ),
                    domain=_txn_domain(self._txn),
                    strict_one=strict_one,
                    raw_mode=self._has_computed_output(),
                    after_refs=after_refs,
                ),
            ),
        )
        return cast("LazyResult[T | None]", self._publish_query_step_lazy(step))

    @pure_lazy
    def lazy_first(
        self: _VersionedReadQueryBuilder[T],
        *,
        after: Sequence[LazyResult[Any]] = (),
    ) -> LazyResult[T | None]:
        return self._versioned_single_row_lazy(strict_one=False, after=after)

    @pure_lazy
    def lazy_execute_one(self: _VersionedReadQueryBuilder[T]) -> LazyResult[T | None]:
        return self._versioned_single_row_lazy(strict_one=True)

    def _versioned_scalar_lazy[R](
        self: _VersionedReadQueryBuilder[T],
        intent_cls: type[Any],
        expected_type: type[R],
    ) -> LazyResult[R]:
        """Publish a scalar read at the transaction's explicit revision.

        Scalar terminals share the single-row terminals' constraint: the
        generic intents only route through versioned storage when the lowering
        context is versioned, so they would count rows in the empty physical
        base table.
        """
        plan = self._txn._get_transaction_plan_lazy()
        flush_pending = getattr(self._txn, "_flush_pending_lazy_ops_to_plan", None)
        raw_flushed_refs = flush_pending() if callable(flush_pending) else ()
        if not isinstance(raw_flushed_refs, list | tuple | set | frozenset):
            raise TypeError("Pending lazy operation refs must be a finite collection")
        flushed_refs = frozenset(ServerPlanRefId(str(ref)) for ref in raw_flushed_refs)
        after_refs = (
            flushed_refs
            | _current_versioned_write_tail_refs(self._txn, plan=plan)
            | frozenset(ServerPlanRefId(str(step.ref_id)) for step in plan._steps)
        )
        step = intent_cls(
            ref_id=ServerPlanRefId(plan._next_ref()),
            model_cls=self._model_cls,
            config=ServerRefs.scalar(
                intent_versioning_extended._VersionedQueryScalarConfig(
                    query_spec=self._build_spec(),
                    revision_id=self._txn._current_revision_source_ref(
                        context="versioned scalar query revision context",
                    ),
                    domain=_txn_domain(self._txn),
                    after_refs=after_refs,
                ),
            ),
        )
        result = cast("LazyResult[R]", self._publish_query_step_lazy(step))
        result._expected_type = expected_type
        return result

    @pure_lazy
    def lazy_count(self: _VersionedReadQueryBuilder[T]) -> LazyResult[int]:
        return self._versioned_scalar_lazy(intent_versioning_extended.VersionedQueryCountIntent, int)

    @pure_lazy
    def lazy_exists(self: _VersionedReadQueryBuilder[T]) -> LazyResult[bool]:
        return self._versioned_scalar_lazy(intent_versioning_extended.VersionedQueryExistsIntent, bool)

    @pure_lazy
    def delete_lazy(self: _VersionedReadQueryBuilder[T]) -> LazyResult[int]:
        """Delete visible rows matched by this versioned write-query view."""
        delete_many = getattr(self._txn, "delete_many_lazy", None)
        if not callable(delete_many):
            msg = "delete() is only available on versioned write transaction queries."
            raise AttributeError(msg)
        plan = self._txn._get_transaction_plan_lazy()
        context_refs = get_versioned_lazy_context_refs(self._txn)
        literal_branch = versioned_lazy_context_literal_branch(context_refs)
        branch_ref_id: ServerPlanRefId | None = None
        if literal_branch is None:
            branch_ref = versioned_lazy_context_branch_ref(
                context_refs,
                context=DiagnosticLabel("versioned query delete branch context"),
            )
            assert branch_ref.ref_id is not None
            branch_ref_id = ServerPlanRefId(branch_ref.ref_id)
        ref_id = ServerPlanRefId(plan._next_ref())
        plan.add_step(
            versioned_query_steps.VersionedQueryDeleteFromSpecStep(
                ref_id,
                self._model_cls,
                versioned_query_steps._VersionedQueryDeleteFromSpecConfig(
                    query_spec=self._build_spec(),
                    branch_id=None if literal_branch is None else str(literal_branch),
                    branch_ref_id=branch_ref_id,
                ),
            ),
        )
        return cast("LazyResult[int]", cast(Any, self._txn)._add_intent_by_ref(ref_id))

    @legacy_sync
    def delete(self: _VersionedReadQueryBuilder[T]) -> int:
        """Delete all matching rows and return the deleted row count."""
        _legacy_delegate_stub()

    @legacy_async
    async def delete_async(self: _VersionedReadQueryBuilder[T]) -> int:
        """Async delete for visible rows matched by this versioned write-query view."""
        _legacy_delegate_stub_async()


class _VersionedWriteQueryBuilder[T: VersionedObjectRow[SysId]](WriteQueryBuilder[T]):
    """Versioned write query builder with version-aware read terminals.

    Query mutation terminals continue to use ``WriteQueryBuilder`` so versioned
    delete/update lowering remains on the write-query path. Read terminals must
    use ``VersionedQueryIntent`` so staged writes and lazy branch bindings are
    interpreted under the active versioned transaction view.
    """

    __slots__ = ("_txn",)

    def __init__(self: Self, txn: object, model_cls: type[T]) -> None:
        plan_owner = cast(Any, txn)
        super().__init__(plan_owner._get_transaction_plan_lazy(), model_cls)
        self._txn = txn
        assert isinstance(txn, VersionedReadTransactionLazyMixin | VersionedWriteTransactionLazyMixin)
        _attach_versioned_query_permissions(txn, self, model_cls)

    def include_deleted(self: Self) -> Self:
        """Include tombstones in the staged-aware logical snapshot."""
        self._include_deleted = True
        return self

    def _update_lazy(
        self: _VersionedWriteQueryBuilder[T],
        *,
        after_refs: frozenset[ServerPlanRefId] = frozenset(),
        **updates: Any,
    ) -> LazyResult[int]:
        """Order a query update after the active publication boundary."""
        plan = cast(Any, self._txn)._get_transaction_plan_lazy()
        result = super()._update_lazy(
            after_refs=after_refs | _current_versioned_write_tail_refs(self._txn, plan=plan),
            **updates,
        )
        return _record_versioned_write_tail(self._txn, result, context="versioned query update")

    @pure_lazy
    def lazy(self: _VersionedWriteQueryBuilder[T]) -> LazyResult[Sequence[T]]:
        return _VersionedReadQueryBuilder.lazy(cast(Any, self))

    @pure_lazy
    def _projection_rows_lazy(self: _VersionedWriteQueryBuilder[T]) -> LazyResult[Sequence[Any]]:
        """Keep tuple projections on the staged-aware versioned read owner."""
        return cast("LazyResult[Sequence[Any]]", self.lazy())

    @overload
    def execute_lazy(
        self: _VersionedWriteQueryBuilder[T],
        *,
        _internal_projection: Literal[False] = False,
    ) -> LazyResult[Sequence[T]]: ...

    @overload
    def execute_lazy(
        self: _VersionedWriteQueryBuilder[T],
        *,
        _internal_projection: Literal[True],
    ) -> LazyResult[list[dict[str, Any]]]: ...

    @pure_lazy
    def execute_lazy(
        self: _VersionedWriteQueryBuilder[T],
        *,
        _internal_projection: bool = False,
    ) -> LazyResult[Sequence[T]] | LazyResult[list[dict[str, Any]]]:
        result = self.lazy()
        if _internal_projection:
            return cast("LazyResult[list[dict[str, Any]]]", result)
        return result

    @pure_lazy
    def lazy_count(self: _VersionedWriteQueryBuilder[T]) -> LazyResult[int]:
        return _VersionedReadQueryBuilder._versioned_scalar_lazy(
            cast(Any, self),
            intent_versioning_extended.VersionedQueryCountIntent,
            int,
        )

    @pure_lazy
    def lazy_exists(self: _VersionedWriteQueryBuilder[T]) -> LazyResult[bool]:
        return _VersionedReadQueryBuilder._versioned_scalar_lazy(
            cast(Any, self),
            intent_versioning_extended.VersionedQueryExistsIntent,
            bool,
        )

    @pure_lazy
    def lazy_first(
        self: _VersionedWriteQueryBuilder[T],
        *,
        after: Sequence[LazyResult[Any]] = (),
    ) -> LazyResult[T | None]:
        """Read the first visible row under the same view as :meth:`lazy`."""
        return _VersionedReadQueryBuilder._versioned_single_row_lazy(
            cast(Any, self),
            strict_one=False,
            after=after,
        )

    @pure_lazy
    def lazy_execute_one(self: _VersionedWriteQueryBuilder[T]) -> LazyResult[T | None]:
        """Require at most one row after all pending versioned writes are visible.

        ``QueryExecuteOneIntent`` resolves versioned models against staged and
        tip storage only, which silently misses rows inherited from ancestor
        revisions on a branch whose tip is not materialized. Single-row reads
        therefore route through the same versioned query lowering as
        :meth:`lazy`, which unions staged writes with the branch's committed
        state.
        """
        return _VersionedReadQueryBuilder._versioned_single_row_lazy(cast(Any, self), strict_one=True)


@pure_lazy
def _check_versioned_read_planning_state(txn: object) -> None:
    for check_name in ("_check_thread", "_check_active"):
        check = getattr(txn, check_name, None)
        if not callable(check):
            raise TypeError(f"Versioned read transaction does not expose {check_name}")
        check()


class VersionedReadTransactionLazyMixin(VersionedReadPlanTarget, ReadTransactionLazyMixin):  # pyright: ignore[reportUntypedBaseClass]
    """Lazy methods for SyncVersionedReadTransaction."""

    def versioned_transaction_planning_snapshot(
        self: VersionedReadTransactionLazyMixin,
    ) -> VersionedTransactionPlanningSnapshot:
        txn = cast(_VersionedReadTxnState, self)
        revision_id = getattr(txn, "_revision_id", None)
        return VersionedTransactionPlanningSnapshot(
            branch_tip_materialization=getattr(txn, "_branch_tip_materialization", None),
            lazy_revision=txn._lazy_revision,
            lazy_branch=getattr(txn, "_lazy_branch", None),
            explicit_base_revision_id=None,
            base_revision_id=revision_id,
            revision_id=revision_id,
            domain=txn.domain,
            staging_context_factory=None,
        )

    @pure_lazy
    def _current_revision_source_ref(
        self: VersionedReadTransactionLazyMixin,
        *,
        context: str,
    ) -> ScalarServerRef[RevisionId]:
        txn = cast(_VersionedReadTxnState, self)
        explicit_read_revision_id = getattr(txn, "_explicit_read_revision_id", None)
        explicit_revision_ref = _literal_revision_source_ref(explicit_read_revision_id)
        if explicit_revision_ref is not None:
            return explicit_revision_ref
        revision_id = getattr(txn, "_revision_id", None)
        revision_ref = _literal_revision_source_ref(revision_id)
        if revision_ref is not None:
            return revision_ref
        try:
            public_revision_id = getattr(self, "revision_id")
        except (AttributeError, RuntimeError):
            public_revision_id = None
        public_revision_ref = _literal_revision_source_ref(public_revision_id)
        if public_revision_ref is not None:
            return public_revision_ref
        lazy_revision_shape = inspect_server_value_shape_for_planning(
            txn._lazy_revision,
            site=context,
        )
        if lazy_revision_shape.has_literal_value:
            lazy_revision_ref = _literal_revision_source_ref(lazy_revision_shape.literal_value)
            if lazy_revision_ref is not None:
                return lazy_revision_ref
        raw_context_refs = get_versioned_context_refs(self)
        if raw_context_refs is not None:
            raw_context_revision_ref = _literal_revision_source_ref(raw_context_refs.revision)
            if raw_context_revision_ref is not None:
                return raw_context_revision_ref
        context_refs = get_versioned_lazy_context_refs(self)
        context_revision_ref = versioned_lazy_context_revision_ref(
            context_refs,
            context=DiagnosticLabel(context),
        )
        if context_revision_ref is not None:
            return context_revision_ref
        return _require_scalar_source_ref(txn._lazy_revision, context=context)

    @pure_lazy
    def query_lazy[T: DatabaseObjectRow](
        self: VersionedReadTransactionLazyMixin,
        model_cls: type[T],
    ) -> Any:
        """Query versioned tables through explicit-revision versioned read intents."""
        if not issubclass(model_cls, VersionedObjectRow):
            return ReadTransactionLazyMixin.query_lazy(
                getattr(cast(Any, self), "base_read_transaction"),
                model_cls,
            )
        return _VersionedReadQueryBuilder(cast(Any, self), cast("type[VersionedObjectRow[SysId]]", model_cls))

    @pure_lazy
    def query_unfiltered_lazy[T: DatabaseObjectRow](
        self: VersionedReadTransactionLazyMixin,
        model_cls: type[T],
        *,
        internal_permission_query_request: InternalPermissionQueryRequest | None = None,
    ) -> Any:
        """Unfiltered query variant with the same versioned routing as ``query_lazy``.

        Inheriting the non-versioned implementation would build a plain
        ``ReadQueryBuilder``, whose terminals compile against the versioned
        model's physical base table. That table is never created for a
        versioned model — rows live in the ``_sparse``/``_tip``/``_staged``
        family — so the read fails with ``TableNotFoundError`` instead of
        reading versioned storage.
        """
        if not issubclass(model_cls, VersionedObjectRow):
            return ReadTransactionLazyMixin.query_unfiltered_lazy(
                getattr(cast(Any, self), "base_read_transaction"),
                model_cls,
                internal_permission_query_request=internal_permission_query_request,
            )
        builder = _VersionedReadQueryBuilder(cast(Any, self), cast("type[VersionedObjectRow[SysId]]", model_cls))
        return builder._without_permission_filtering(internal_permission_query_request)

    @pure_lazy
    def select_one_raw_lazy[T: VersionedObjectRow[SysId]](
        self: VersionedReadTransactionLazyMixin,
        model_cls: type[T],
        object_id: LazyResult[SysId],
    ) -> LazyResult[dict[str, object] | None]:
        _check_versioned_read_planning_state(self)
        plan = self._get_transaction_plan_lazy()
        out_ref = ServerPlanRefId(plan._next_ref())
        rows_ref = ServerPlanRefId(f"{out_ref}.rows")
        after_refs = _current_versioned_write_tail_refs(self, plan=plan) | frozenset(
            ServerPlanRefId(str(step.ref_id)) for step in plan._steps
        )
        self._add_intent(
            intent_versioning_extended.VersionedQueryFirstIntent(
                ref_id=rows_ref,
                model_cls=model_cls,
                config=ServerRefs.scalar(
                    intent_versioning_extended._VersionedQueryFirstConfig(
                        query_spec=_build_versioned_raw_query_spec(
