    @pure_lazy
    def get_history_lazy[T: VersionedObjectRow](
        self: VersionedReadTransactionLazyMixin,
        model_cls: type[T],
        object_id: SysId | LazyResult[SysId],
    ) -> LazyResult[Sequence[HistoryEntry[T]]]:
        query_cls = _plan_backed_revision_history_query_type()
        query = query_cls(model_cls, cast("Any", _txn_domain(self).revision_model), self)
        if isinstance(object_id, LazyResult):
            source_ref = _published_lazy_ref_id(
                object_id,
                context="get_history_lazy object_id",
            )
            if source_ref is None:
                history_object_id: SysId | ScalarServerRef[SysId] = _require_concrete_lazy_input(
                    object_id,
                    context="get_history_lazy object_id",
                )
            else:
                history_object_id = ServerRefs.from_ref_id(
                    ServerPlanRefId(source_ref),
                    variant="scalar",
                    type_hint=SysId,
                )
        else:
            history_object_id = object_id
        query._object_ids = [
            history_object_id,
        ]
        return cast("LazyResult[Sequence[HistoryEntry[T]]]", query._resolve_revision_history_entries_lazy())

