    @pure_lazy
    def is_revision_materialized_lazy(
        self: VersionedReadTransactionLazyMixin,
        revision_id: RevisionId | LazyResult[RevisionId] | ScalarServerRef[RevisionId],
        *,
        skip_data_check: bool = False,
    ) -> LazyResult[bool]:
        del skip_data_check
        plan = self._get_transaction_plan_lazy()
        revision_ref = self._metadata_revision_ref(revision_id)
        domain = _txn_domain(self)

        revision_exists = self.revision_exists_in_metadata_lazy(revision_ref)
        revision_exists_ref = _published_lazy_ref_id(
            revision_exists,
            context="is_revision_materialized_lazy revision_exists",
        )
        if revision_exists_ref is None:
            msg = "revision_exists_in_metadata_lazy() must publish a step ref"
            raise RuntimeError(msg)

        parent_exists = self.has_any_parent_lazy(revision_ref)
        parent_exists_ref = _published_lazy_ref_id(
            parent_exists,
            context="is_revision_materialized_lazy parent_exists",
        )
        if parent_exists_ref is None:
            msg = "has_any_parent_lazy() must publish a step ref"
            raise RuntimeError(msg)

        no_parent_ref = ServerPlanRefId(plan._next_ref())
        plan.add_step(
            _InvertBoolStep(
                no_parent_ref,
                _InvertBoolConfig(source_ref_id=ServerPlanRefId(parent_exists_ref)),
            ),
        )

        root_ref = ServerPlanRefId(plan._next_ref())
        plan.add_step(
            versioned_lazy_support.BoolAndStep(
                ServerPlanRefId(root_ref),
                left_ref=revision_exists_ref,
                right_ref=str(no_parent_ref),
            ),
        )

        anchor_exists_ref = ServerPlanRefId(plan._next_ref())
        self._add_intent(
            intent_query_extended.QueryExistsIntent(
                ref_id=anchor_exists_ref,
                model_cls=domain.revision_branch_index_model,
                config=intent_query_extended._QueryExistsConfig(
                    query_spec=revision_metadata_query_specs.materialized_anchor_exists_spec(
                        domain,
                        revision_id=revision_ref,
                    ),
                ),
            ),
        )

        tip_exists_ref = ServerPlanRefId(plan._next_ref())
        self._add_intent(
            intent_query_extended.QueryExistsIntent(
                ref_id=tip_exists_ref,
                model_cls=domain.branch_model,
                config=intent_query_extended._QueryExistsConfig(
                    query_spec=revision_metadata_query_specs.branch_tip_exists_spec(
                        domain,
                        revision_id=revision_ref,
                    ),
                ),
            ),
        )

        anchored_ref = ServerPlanRefId(plan._next_ref())
        plan.add_step(
            versioned_lazy_support.BoolOrStep(
                ServerPlanRefId(anchored_ref),
                left_ref=str(anchor_exists_ref),
                right_ref=str(tip_exists_ref),
            ),
        )

        out_ref = ServerPlanRefId(plan._next_ref())
        plan.add_step(
            versioned_lazy_support.BoolOrStep(
                ServerPlanRefId(out_ref),
                left_ref=str(root_ref),
                right_ref=str(anchored_ref),
            ),
        )
        return cast(LazyResult[bool], self._add_intent_by_ref(out_ref))

    @pure_lazy
    def get_branch_tip_lazy(
        self: VersionedReadTransactionLazyMixin,
